definition:
CREATE OR REPLACE FUNCTION public.agent_v1_commit_record_overview_layout_apply(p_org_id uuid, p_user_id uuid, p_entity_type text, p_surface text, p_expected_version integer, p_config jsonb, p_proposal_id uuid, p_request_id uuid, p_correlation_id uuid, p_intent_json jsonb, p_result_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    layout_id uuid;
    cur jsonb;
    v_old integer;
    before_h text;
    after_h text;
    out_row jsonb;
BEGIN
    SELECT rol.id, coalesce(rol.config, '{}'::jsonb)
    INTO layout_id, cur
    FROM public.record_overview_layouts rol
    WHERE rol.org_id = p_org_id
      AND rol.entity_type = p_entity_type
      AND rol.surface = p_surface
    FOR UPDATE;

    IF NOT FOUND THEN
        IF p_expected_version IS DISTINCT FROM 0 THEN
            RAISE EXCEPTION 'agent_v1:no_record_overview_layout_row';
        END IF;

        before_h := encode(extensions.digest(convert_to('{}'::jsonb::text, 'UTF8'), 'sha256'), 'hex');
        after_h := encode(extensions.digest(convert_to(p_config::text, 'UTF8'), 'sha256'), 'hex');

        INSERT INTO public.record_overview_layouts (org_id, entity_type, surface, template_key, config, is_active)
        VALUES (p_org_id, p_entity_type, p_surface, 'default_record_overview', p_config, true)
        RETURNING id INTO layout_id;

        cur := '{}'::jsonb;
    ELSE
        v_old := coalesce((cur->>'version')::integer, 0);
        IF v_old IS DISTINCT FROM p_expected_version THEN
            RAISE EXCEPTION 'agent_v1:stale_record_overview_layout_version';
        END IF;

        before_h := encode(extensions.digest(convert_to(cur::text, 'UTF8'), 'sha256'), 'hex');
        after_h := encode(extensions.digest(convert_to(p_config::text, 'UTF8'), 'sha256'), 'hex');

        UPDATE public.record_overview_layouts
        SET
            config = p_config,
            updated_at = now()
        WHERE id = layout_id
          AND org_id = p_org_id;
    END IF;

    INSERT INTO public.agent_v1_record_layout_proposals (
        proposal_id,
        request_id,
        correlation_id,
        org_id,
        user_id,
        record_overview_layout_id,
        intent_json,
        before_hash,
        after_hash
    )
    VALUES (
        p_proposal_id,
        p_request_id,
        p_correlation_id,
        p_org_id,
        p_user_id,
        layout_id,
        p_intent_json,
        before_h,
        after_h
    );

    INSERT INTO public.agent_v1_record_layout_apply_audit (
        result_id,
        proposal_id,
        org_id,
        user_id,
        record_overview_layout_id,
        terminal_status,
        applied_config_version
    )
    VALUES (
        p_result_id,
        p_proposal_id,
        p_org_id,
        p_user_id,
        layout_id,
        'success',
        coalesce((p_config->>'version')::integer, 0)
    );

    SELECT to_jsonb(rol.*)
    INTO out_row
    FROM public.record_overview_layouts rol
    WHERE rol.id = layout_id;

    RETURN out_row;
END;
$function$

CREATE OR REPLACE FUNCTION public.agent_v2_commit_field_visibility_apply(p_org_id uuid, p_user_id uuid, p_field_definition_id uuid, p_expected_updated_at text, p_is_visible_in_form boolean, p_is_visible_in_drawer boolean, p_is_visible_in_table boolean, p_is_visible_in_public_booking boolean, p_proposal_id uuid, p_request_id uuid, p_correlation_id uuid, p_intent_json jsonb, p_result_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    fd public.field_definitions%ROWTYPE;
    v_lock timestamptz;
    exp_ts timestamptz;
    before_h text;
    after_h text;
    out_row jsonb;
    before_vis jsonb;
    after_vis jsonb;
BEGIN
    SELECT *
    INTO fd
    FROM public.field_definitions
    WHERE id = p_field_definition_id
      AND org_id = p_org_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'agent_v2:field_definition_not_found';
    END IF;

    v_lock := coalesce(fd.updated_at, fd.created_at);

    IF v_lock IS NULL THEN
        RAISE EXCEPTION 'agent_v2:field_definition_not_found';
    END IF;

    exp_ts := p_expected_updated_at::timestamptz;

    IF v_lock IS DISTINCT FROM exp_ts THEN
        RAISE EXCEPTION 'agent_v2:stale_field_definition';
    END IF;

    before_vis := jsonb_build_object(
        'is_visible_in_form', fd.is_visible_in_form,
        'is_visible_in_drawer', fd.is_visible_in_drawer,
        'is_visible_in_table', fd.is_visible_in_table,
        'is_visible_in_public_booking', fd.is_visible_in_public_booking
    );
    before_h := encode(extensions.digest(convert_to(before_vis::text, 'UTF8'), 'sha256'), 'hex');

    after_vis := jsonb_build_object(
        'is_visible_in_form', p_is_visible_in_form,
        'is_visible_in_drawer', p_is_visible_in_drawer,
        'is_visible_in_table', p_is_visible_in_table,
        'is_visible_in_public_booking', p_is_visible_in_public_booking
    );
    after_h := encode(extensions.digest(convert_to(after_vis::text, 'UTF8'), 'sha256'), 'hex');

    UPDATE public.field_definitions
    SET
        is_visible_in_form = p_is_visible_in_form,
        is_visible_in_drawer = p_is_visible_in_drawer,
        is_visible_in_table = p_is_visible_in_table,
        is_visible_in_public_booking = p_is_visible_in_public_booking,
        updated_at = now()
    WHERE id = p_field_definition_id
      AND org_id = p_org_id;

    INSERT INTO public.agent_v2_field_visibility_proposals (
        proposal_id,
        request_id,
        correlation_id,
        org_id,
        user_id,
        field_definition_id,
        intent_json,
        before_hash,
        after_hash
    )
    VALUES (
        p_proposal_id,
        p_request_id,
        p_correlation_id,
        p_org_id,
        p_user_id,
        p_field_definition_id,
        p_intent_json,
        before_h,
        after_h
    );

    INSERT INTO public.agent_v2_field_visibility_apply_audit (
        result_id,
        proposal_id,
        org_id,
        user_id,
        field_definition_id,
        terminal_status,
        applied_updated_at
    )
    VALUES (
        p_result_id,
        p_proposal_id,
        p_org_id,
        p_user_id,
        p_field_definition_id,
        'success',
        (SELECT updated_at FROM public.field_definitions WHERE id = p_field_definition_id)
    );

    SELECT to_jsonb(f.*)
    INTO out_row
    FROM public.field_definitions f
    WHERE f.id = p_field_definition_id;

    RETURN out_row;
END;
$function$

CREATE OR REPLACE FUNCTION public.author_operational_expectation(p_org_id uuid, p_actor_user_id uuid, p_act jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_key text := nullif(p_act->>'idempotency_key','');
    v_fingerprint text := p_act->>'payload_fingerprint';
    v_existing public.operational_expectations%ROWTYPE;
    v_new public.operational_expectations%ROWTYPE;
    v_mutation_id uuid := gen_random_uuid();
    v_verb text := p_act->>'verb';
    v_modality text := p_act->>'modality';
    v_author_class text := p_act->>'author_class';
    v_authority_key text := p_act->>'authority_key';
    v_transition text := nullif(p_act->>'transition_type','');
    v_supersedes uuid := nullif(p_act->>'supersedes_expectation_id','')::uuid;
    v_valid_from timestamptz := (p_act->>'valid_from')::timestamptz;
    -- authority resolution inputs (server-trusted; NOT a caller standing choice)
    v_holder_id text := nullif(p_act->>'authority_holder_id','');
    v_scope_type text := COALESCE(nullif(p_act->>'authority_scope_type',''), 'organization');
    v_scope_id text := nullif(p_act->>'authority_scope_id','');
    v_standing text;
    v_assignment uuid;
    v_matched_scope text;
BEGIN
    IF v_key IS NULL THEN RAISE EXCEPTION 'oe_missing_idempotency_key' USING ERRCODE = '22023'; END IF;

    -- Compute standing AUTHORITATIVELY. predicted → model; AI → proposed; else a
    -- held-authority holder self-ratifies to binding, otherwise proposed.
    IF v_modality = 'predicted' THEN
        v_standing := 'model';
    ELSIF v_author_class = 'ai' THEN
        v_standing := 'proposed';
    ELSE
        v_assignment := public.resolve_held_operational_authority(
            p_org_id, v_author_class, COALESCE(v_holder_id, p_actor_user_id::text), v_authority_key, v_scope_type, v_scope_id, now());
        IF v_assignment IS NOT NULL THEN
            v_standing := 'binding';
            v_matched_scope := v_scope_type;
        ELSE
            v_standing := 'proposed';
        END IF;
    END IF;

    BEGIN
        INSERT INTO public.operational_expectations (
            org_id, authority_key, author_class, modality, subject_kind, subject_ref, condition,
            temporal_frame, beneficiary, verb, transition_type, supersedes_expectation_id, standing,
            footprint, valid_from, valid_to, config_version_ref, authored_by_user_id, authored_by_label,
            idempotency_key, payload_fingerprint, authority_assignment_id, authority_matched_scope
        ) VALUES (
            p_org_id, v_authority_key, v_author_class, v_modality, p_act->>'subject_kind', p_act->'subject_ref',
            p_act->'condition', p_act->'temporal_frame',
            CASE WHEN p_act->'beneficiary' = 'null'::jsonb THEN NULL ELSE p_act->'beneficiary' END,
            v_verb, v_transition, v_supersedes, v_standing, COALESCE(p_act->'footprint','{}'::jsonb),
            v_valid_from, nullif(p_act->>'valid_to','')::timestamptz,
            CASE WHEN p_act->'config_version_ref' = 'null'::jsonb THEN NULL ELSE p_act->'config_version_ref' END,
            p_actor_user_id, nullif(p_act->>'authored_by_label',''), v_key, v_fingerprint, v_assignment, v_matched_scope
        ) RETURNING * INTO v_new;

        INSERT INTO public.mutation_events (
            org_id, mutation_id, command_key, domain, subject_id, subject_type,
            previous_state, new_state, operator_id, origin, context_payload, committed_at, effective_at
        ) VALUES (
            p_org_id, v_mutation_id, 'author_expectation', 'operational_expectations', v_new.id, 'operational_expectation',
            v_supersedes::text, v_verb || ':' || v_modality || ':' || v_standing, p_actor_user_id::text, 'api',
            jsonb_build_object('expectation_id', v_new.id, 'verb', v_verb, 'modality', v_modality,
                'transition_type', v_transition, 'standing', v_standing, 'authority_key', v_authority_key,
                'authority_assignment_id', v_assignment, 'authority_matched_scope', v_matched_scope,
                'self_ratified', (v_standing = 'binding'), 'lineage_root_id', v_new.lineage_root_id,
                'idempotency_key', v_key),
            now(), v_valid_from
        );

        RETURN jsonb_build_object('ok', true, 'disposition', 'created', 'idempotent', false,
            'expectation_id', v_new.id, 'authoring_act_event_id', v_mutation_id, 'verb', v_new.verb,
            'modality', v_new.modality, 'transition_type', v_new.transition_type, 'standing', v_new.standing,
            'self_ratified', (v_new.standing = 'binding'), 'authority_assignment_id', v_assignment,
            'supersedes_expectation_id', v_new.supersedes_expectation_id, 'lineage_root_id', v_new.lineage_root_id,
            'authored_at', v_new.authored_at);

    EXCEPTION WHEN unique_violation THEN
        SELECT * INTO v_existing FROM public.operational_expectations WHERE org_id = p_org_id AND idempotency_key = v_key;
        IF NOT FOUND THEN RAISE; END IF;
        IF v_existing.payload_fingerprint IS DISTINCT FROM v_fingerprint THEN RAISE EXCEPTION 'oe_idempotency_conflict' USING ERRCODE = '23505'; END IF;
        RETURN jsonb_build_object('ok', true, 'disposition', 'existing', 'idempotent', true,
            'expectation_id', v_existing.id, 'authoring_act_event_id', v_existing.id, 'verb', v_existing.verb,
            'modality', v_existing.modality, 'transition_type', v_existing.transition_type, 'standing', v_existing.standing,
            'self_ratified', (v_existing.standing = 'binding'), 'authority_assignment_id', v_existing.authority_assignment_id,
            'supersedes_expectation_id', v_existing.supersedes_expectation_id, 'lineage_root_id', v_existing.lineage_root_id,
            'authored_at', v_existing.authored_at);
    END;
END;
$function$

CREATE OR REPLACE FUNCTION public.discounted_cents(base_cents integer, pct numeric)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare
  cents int;
begin
  cents := round(base_cents * pct)::int;
  return public.round_to_nearest_5_cents(cents);
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_childcare_charge_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.billable_source_type = 'enrollment_agreement' AND OLD.status <> 'draft' THEN
            RAISE EXCEPTION 'posted childcare charge % is immutable: DELETE not allowed; record a reversal/credit/replacement via source_charge_id', OLD.id
                USING ERRCODE = '0A000';
        END IF;
        RETURN OLD;
    END IF;

    -- UPDATE: only governs posted childcare charges; drafts and job rows pass.
    IF OLD.billable_source_type = 'enrollment_agreement' AND OLD.status <> 'draft' THEN
        IF NEW.amount_cents IS DISTINCT FROM OLD.amount_cents
            OR NEW.charge_category IS DISTINCT FROM OLD.charge_category
            OR NEW.charge_type IS DISTINCT FROM OLD.charge_type
            OR NEW.currency_code IS DISTINCT FROM OLD.currency_code
            OR NEW.billable_source_type IS DISTINCT FROM OLD.billable_source_type
            OR NEW.billable_source_id IS DISTINCT FROM OLD.billable_source_id
            OR NEW.source_charge_id IS DISTINCT FROM OLD.source_charge_id
            OR NEW.service_date IS DISTINCT FROM OLD.service_date THEN
            RAISE EXCEPTION 'posted childcare charge % is immutable: financial fields cannot change in place; record a reversal/credit/replacement via source_charge_id', OLD.id
                USING ERRCODE = '0A000';
        END IF;
        -- Status may advance among posted states (driven by payments) but never
        -- revert to draft or void in place (void = a reversal row, not an edit).
        IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status = ANY (ARRAY['draft'::text, 'void'::text]) THEN
            RAISE EXCEPTION 'posted childcare charge % cannot transition to % in place; record a reversal via source_charge_id', OLD.id, NEW.status
                USING ERRCODE = '0A000';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_communication_scheduled_sends_org_matches_entities()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    opp_org uuid;
    person_org uuid;
BEGIN
    SELECT o.org_id INTO opp_org FROM public.opportunities o WHERE o.id = NEW.entity_id;
    IF opp_org IS NULL OR opp_org <> NEW.org_id THEN
        RAISE EXCEPTION 'communication_scheduled_sends: entity org mismatch' USING ERRCODE = '23514';
    END IF;
    SELECT p.org_id INTO person_org FROM public.persons p WHERE p.id = NEW.recipient_person_id;
    IF person_org IS NULL OR person_org <> NEW.org_id THEN
        RAISE EXCEPTION 'communication_scheduled_sends: recipient person org mismatch' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_form_submissions_submitted_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP <> 'UPDATE' THEN
        RETURN NEW;
    END IF;

    IF OLD.status IS DISTINCT FROM 'submitted'::text AND OLD.status IS DISTINCT FROM 'void'::text THEN
        RETURN NEW;
    END IF;

    IF NEW.form_definition_version_id IS DISTINCT FROM OLD.form_definition_version_id
        OR NEW.form_definition_id IS DISTINCT FROM OLD.form_definition_id
    THEN
        RAISE EXCEPTION 'form_submissions: finalized rows cannot change payload or form version linkage';
    END IF;

    IF public.form_submission_canonical_capture(NEW.payload) IS DISTINCT FROM public.form_submission_canonical_capture(OLD.payload)
    THEN
        RAISE EXCEPTION 'form_submissions: finalized rows cannot change captured answers';
    END IF;

    IF OLD.status = 'submitted'::text AND NEW.status IS DISTINCT FROM OLD.status THEN
        IF NEW.status <> 'void'::text THEN
            RAISE EXCEPTION 'form_submissions: submitted rows may only transition to void';
        END IF;
    ELSIF OLD.status = 'void'::text AND NEW.status IS DISTINCT FROM OLD.status THEN
        RAISE EXCEPTION 'form_submissions: void rows cannot change status';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_jobs_work_unit_same_org()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  w_org uuid;
BEGIN
  IF NEW.work_unit_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT w.org_id INTO w_org
  FROM public.work_units AS w
  WHERE w.id = NEW.work_unit_id;

  IF w_org IS NULL THEN
    RAISE EXCEPTION 'jobs.work_unit_id % does not reference an existing work unit', NEW.work_unit_id
      USING ERRCODE = '23503';
  END IF;

  IF NEW.org_id IS DISTINCT FROM w_org THEN
    RAISE EXCEPTION 'jobs.org_id (%) must match work_units.org_id (%) for work_unit_id % (job org and work unit org must be the same tenant)',
      NEW.org_id, w_org, NEW.work_unit_id
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_operational_tasks_org_matches_opportunity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    opp_org uuid;
BEGIN
    IF NEW.entity_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT o.org_id INTO opp_org FROM public.opportunities o WHERE o.id = NEW.entity_id;
    IF opp_org IS NULL OR opp_org <> NEW.org_id THEN
        RAISE EXCEPTION 'operational_tasks: entity org mismatch' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_opportunities_work_unit_same_org()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  w_org uuid;
BEGIN
  IF NEW.work_unit_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT w.org_id INTO w_org
  FROM public.work_units AS w
  WHERE w.id = NEW.work_unit_id;

  IF w_org IS NULL THEN
    RAISE EXCEPTION 'opportunities.work_unit_id % does not reference an existing work unit', NEW.work_unit_id
      USING ERRCODE = '23503';
  END IF;

  IF NEW.org_id IS DISTINCT FROM w_org THEN
    RAISE EXCEPTION 'opportunities.org_id (%) must match work_units.org_id (%) for work_unit_id % (opportunity org and work unit org must be the same tenant)',
      NEW.org_id, w_org, NEW.work_unit_id
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_task_assist_proposals_org_matches_opportunity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    opp_org uuid;
BEGIN
    SELECT o.org_id INTO opp_org FROM public.opportunities o WHERE o.id = NEW.entity_id;
    IF opp_org IS NULL THEN
        RAISE EXCEPTION 'task_assist_proposals: entity_id % not found', NEW.entity_id USING ERRCODE = '23503';
    END IF;
    IF opp_org <> NEW.org_id THEN
        RAISE EXCEPTION 'task_assist_proposals: org_id does not match opportunity.org_id' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.execute_lead_status_mutation(p_org_id uuid, p_opportunity_id uuid, p_new_status_key text, p_operator_id text, p_origin text, p_context_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_old_status_key text;
    v_mutation_id    uuid := gen_random_uuid();
begin
    -- Read current state (will error if not found / wrong org)
    select status_key into v_old_status_key
    from opportunities
    where id = p_opportunity_id and org_id = p_org_id
    for update;

    if not found then
        raise exception 'opportunity_not_found';
    end if;

    if v_old_status_key = p_new_status_key then
        raise exception 'no_state_change';
    end if;

    -- Write state
    update opportunities
    set status_key = p_new_status_key,
        updated_at = now()
    where id = p_opportunity_id and org_id = p_org_id;

    -- Write outbox (same transaction — atomicity guaranteed)
    insert into mutation_events (
        org_id, mutation_id, command_key, domain,
        subject_id, subject_type,
        previous_state, new_state,
        operator_id, origin, context_payload,
        committed_at, effective_at
    ) values (
        p_org_id, v_mutation_id, 'update_lead_status', 'lead_status',
        p_opportunity_id, 'opportunity',
        v_old_status_key, p_new_status_key,
        p_operator_id, p_origin, p_context_payload,
        now(), now()
    );

    return jsonb_build_object(
        'ok',             true,
        'mutation_id',    v_mutation_id,
        'previous_state', v_old_status_key,
        'new_state',      p_new_status_key
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.execute_processing_identity_group(p_org_id uuid, p_actor text, p_idempotency_key text, p_operations jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_refs   jsonb := '{}'::jsonb;
    v_op     jsonb;
    v_op_id  text;
    v_key    text;
    v_pl     jsonb;
    v_new_id uuid;
    v_person uuid;
    v_house  uuid;
    v_role   text;
BEGIN
    FOR v_op IN SELECT * FROM jsonb_array_elements(p_operations)
    LOOP
        v_op_id := v_op ->> 'op_id';
        v_key   := v_op ->> 'command_key';
        v_pl    := v_op -> 'payload';

        IF v_key = 'create_person' THEN
            INSERT INTO persons (org_id, first_name, last_name, email, phone)
            VALUES (
                p_org_id,
                v_pl ->> 'first_name',
                v_pl ->> 'last_name',
                v_pl ->> 'email',
                v_pl ->> 'phone'
            )
            RETURNING id INTO v_new_id;

        ELSIF v_key = 'create_household' THEN
            INSERT INTO customers (org_id, name)
            VALUES (p_org_id, coalesce(v_pl ->> 'household_name', 'Household'))
            RETURNING id INTO v_new_id;

        ELSIF v_key = 'link_person_to_household' THEN
            v_person := public.processing_resolve_ref(v_pl ->> 'person_id', v_refs)::uuid;
            v_house  := public.processing_resolve_ref(v_pl ->> 'household_id', v_refs)::uuid;
            v_role   := coalesce(v_pl ->> 'role_type', 'primary_contact');
            INSERT INTO customer_persons (org_id, customer_id, person_id, role_type)
            VALUES (p_org_id, v_house, v_person, v_role)
            ON CONFLICT (org_id, customer_id, person_id, role_type) DO UPDATE SET role_type = EXCLUDED.role_type
            RETURNING id INTO v_new_id;

        ELSIF v_key IN ('create_child', 'link_child_to_household') THEN
            v_house := public.processing_resolve_ref(v_pl ->> 'household_id', v_refs)::uuid;
            INSERT INTO customer_members (
                org_id, customer_id, person_id, display_name, first_name, last_name, dob, relationship
            )
            VALUES (
                p_org_id,
                v_house,
                NULLIF(public.processing_resolve_ref(v_pl ->> 'person_id', v_refs), '')::uuid,
                coalesce(v_pl ->> 'display_name', 'Child'),
                v_pl ->> 'first_name',
                v_pl ->> 'last_name',
                NULLIF(v_pl ->> 'dob', '')::date,
                coalesce(v_pl ->> 'relationship', 'child')
            )
            RETURNING id INTO v_new_id;

        ELSE
            RAISE EXCEPTION 'unsupported_atomic_group_command:%', v_key;
        END IF;

        v_refs := jsonb_set(v_refs, ARRAY[v_op_id], to_jsonb(v_new_id::text));
    END LOOP;

    RETURN jsonb_build_object('ok', true, 'refs', v_refs);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_quote_pricing(p_vertical_slug text, p_service_key text, p_sqft_key text, p_frequency_key text, p_addon_keys text[] DEFAULT '{}'::text[])
 RETURNS TABLE(out_vertical_slug text, out_service_key text, out_sqft_key text, out_frequency_key text, first_clean_cents integer, recurring_cents integer, addons_total_cents integer, total_first_visit_cents integer, price_breakdown text, is_manual_quote boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_vertical_id uuid;
  v_service_id uuid;
  v_sqft_tier_id uuid;
  v_frequency_id uuid;
  v_first integer;
  v_recurring integer;
  v_addons integer;
  v_freq_label text;
  v_discount_label text;
  v_org_id uuid;
  v_service_offering_id uuid;
  v_dimension_value_id uuid;
  v_initial_mode_id uuid;
  v_recurring_mode_id uuid;
  v_plan_template_id uuid;
BEGIN
  IF lower(p_service_key) IN ('move_out_heavy', 'move-out', 'move_out', 'heavy_clean', 'moveout') THEN
    out_vertical_slug := p_vertical_slug;
    out_service_key := p_service_key;
    out_sqft_key := p_sqft_key;
    out_frequency_key := p_frequency_key;
    first_clean_cents := NULL;
    recurring_cents := NULL;
    addons_total_cents := NULL;
    total_first_visit_cents := NULL;
    price_breakdown := 'Manual quote required';
    is_manual_quote := true;
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT id INTO v_vertical_id
  FROM public.verticals
  WHERE slug = p_vertical_slug AND is_active = true
  LIMIT 1;

  IF v_vertical_id IS NULL THEN
    RAISE EXCEPTION 'Unknown vertical slug: %', p_vertical_slug;
  END IF;

  SELECT ps.id INTO v_service_id
  FROM public.pricing_services ps
  WHERE ps.vertical_id = v_vertical_id
    AND ps.service_key = p_service_key
    AND ps.is_active = true
  LIMIT 1;

  IF v_service_id IS NULL THEN
    RAISE EXCEPTION 'Unknown service_key for %: %', p_vertical_slug, p_service_key;
  END IF;

  SELECT st.id, st.dimension_value_id INTO v_sqft_tier_id, v_dimension_value_id
  FROM public.pricing_square_footage_tiers st
  WHERE st.vertical_id = v_vertical_id
    AND st.tier_key = p_sqft_key
    AND st.is_active = true
  LIMIT 1;

  IF v_sqft_tier_id IS NULL THEN
    RAISE EXCEPTION 'Unknown sqft tier_key for %: %', p_vertical_slug, p_sqft_key;
  END IF;

  SELECT ps.service_offering_id, so.org_id
    INTO v_service_offering_id, v_org_id
  FROM public.pricing_services ps
  LEFT JOIN public.service_offerings so ON so.id = ps.service_offering_id
  WHERE ps.id = v_service_id
  LIMIT 1;

  IF v_service_offering_id IS NULL OR v_org_id IS NULL THEN
    RAISE EXCEPTION 'Missing first_clean price for % / % / %', p_vertical_slug, p_service_key, p_sqft_key;
  END IF;

  IF v_dimension_value_id IS NULL THEN
    RAISE EXCEPTION 'Missing first_clean price for % / % / %', p_vertical_slug, p_service_key, p_sqft_key;
  END IF;

  SELECT pm.id INTO v_initial_mode_id
  FROM public.pricing_modes pm
  WHERE pm.org_id = v_org_id
    AND pm.mode_key = 'initial'
    AND pm.is_active = true
    AND (pm.vertical_id IS NULL OR pm.vertical_id = v_vertical_id)
  ORDER BY pm.sort_order NULLS LAST, pm.id
  LIMIT 1;

  IF v_initial_mode_id IS NULL THEN
    RAISE EXCEPTION 'Missing first_clean price for % / % / %', p_vertical_slug, p_service_key, p_sqft_key;
  END IF;

  SELECT pm.id INTO v_recurring_mode_id
  FROM public.pricing_modes pm
  WHERE pm.org_id = v_org_id
    AND pm.mode_key = 'recurring'
    AND pm.is_active = true
    AND (pm.vertical_id IS NULL OR pm.vertical_id = v_vertical_id)
  ORDER BY pm.sort_order NULLS LAST, pm.id
  LIMIT 1;

  SELECT mtx.amount_cents INTO v_first
  FROM public.pricing_matrix mtx
  WHERE mtx.org_id = v_org_id
    AND mtx.vertical_id = v_vertical_id
    AND mtx.service_offering_id = v_service_offering_id
    AND mtx.pricing_mode_id = v_initial_mode_id
    AND mtx.pricing_dimension_value_id = v_dimension_value_id
    AND mtx.service_plan_template_id IS NULL
    AND mtx.currency = 'USD'
    AND mtx.is_active = true
  LIMIT 1;

  IF v_first IS NULL THEN
    RAISE EXCEPTION 'Missing first_clean price for % / % / %', p_vertical_slug, p_service_key, p_sqft_key;
  END IF;

  v_recurring := NULL;
  v_freq_label := NULL;
  v_discount_label := NULL;
  v_plan_template_id := NULL;

  IF coalesce(trim(p_frequency_key), '') <> '' THEN
    SELECT pf.id, pf.frequency_label, pf.discount_label, pf.service_plan_template_id
      INTO v_frequency_id, v_freq_label, v_discount_label, v_plan_template_id
    FROM public.pricing_frequencies pf
    WHERE pf.vertical_id = v_vertical_id
      AND pf.frequency_key = p_frequency_key
      AND pf.is_active = true
    LIMIT 1;

    IF v_frequency_id IS NOT NULL
       AND v_recurring_mode_id IS NOT NULL
       AND v_plan_template_id IS NOT NULL THEN
      SELECT mtx.amount_cents INTO v_recurring
      FROM public.pricing_matrix mtx
      WHERE mtx.org_id = v_org_id
        AND mtx.vertical_id = v_vertical_id
        AND mtx.service_offering_id = v_service_offering_id
        AND mtx.pricing_mode_id = v_recurring_mode_id
        AND mtx.pricing_dimension_value_id = v_dimension_value_id
        AND mtx.service_plan_template_id = v_plan_template_id
        AND mtx.currency = 'USD'
        AND mtx.is_active = true
      LIMIT 1;
    END IF;
  END IF;

  SELECT coalesce(sum(pa.amount_cents), 0) INTO v_addons
  FROM public.pricing_addons pa
  WHERE pa.vertical_id = v_vertical_id
    AND pa.is_active = true
    AND (coalesce(array_length(p_addon_keys, 1), 0) > 0 AND pa.addon_key = ANY (p_addon_keys));

  out_vertical_slug := p_vertical_slug;
  out_service_key := p_service_key;
  out_sqft_key := p_sqft_key;
  out_frequency_key := p_frequency_key;

  first_clean_cents := v_first;
  recurring_cents := v_recurring;
  addons_total_cents := v_addons;
  total_first_visit_cents := v_first + v_addons;

  price_breakdown :=
    'Sq Ft tier: ' || p_sqft_key ||
    ' | Service: ' || p_service_key ||
    ' | First cleaning (base): $' || to_char(v_first/100.0, 'FM999990.00') ||
    CASE WHEN v_addons > 0 THEN
      ' | Add-ons: $' || to_char(v_addons/100.0, 'FM999990.00')
    ELSE '' END ||
    ' | First visit total: $' || to_char((v_first + v_addons)/100.0, 'FM999990.00') ||
    CASE WHEN v_recurring IS NOT NULL THEN
      ' | Recurring (' || coalesce(v_freq_label,'') || '): $' ||
      to_char(v_recurring/100.0, 'FM999990.00') || ' / visit' ||
      CASE WHEN v_discount_label IS NOT NULL THEN ' (' || v_discount_label || ')' ELSE '' END
    ELSE '' END;

  is_manual_quote := false;
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  insert into public.user_profiles (id, role)
  values (new.id, 'ops');
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.locations_parent_same_org()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  parent_org uuid;
begin
  if new.parent_location_id is null then
    return new;
  end if;

  select org_id into parent_org
  from public.locations
  where id = new.parent_location_id;

  if parent_org is null then
    raise exception 'Parent location % not found', new.parent_location_id;
  end if;

  if parent_org <> new.org_id then
    raise exception 'Parent location org_id % does not match child org_id %', parent_org, new.org_id;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.next_org_scoped_record_number(p_org_id uuid, p_entity text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_entity text;
  v_tbl text;
  v_col text;
  v_next bigint;
BEGIN
  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'next_org_scoped_record_number: org_id is required';
  END IF;

  v_entity := lower(trim(p_entity));
  IF v_entity IS NULL OR v_entity = '' THEN
    RAISE EXCEPTION 'next_org_scoped_record_number: entity is required';
  END IF;

  -- Serialize allocators per org + entity (transaction-scoped; released at commit/rollback).
  PERFORM pg_advisory_xact_lock(hashtext(p_org_id::text || '|' || v_entity));

  CASE v_entity
    WHEN 'customer' THEN
      v_tbl := 'customers';
      v_col := 'customer_number';
    WHEN 'job' THEN
      v_tbl := 'jobs';
      v_col := 'job_number';
    WHEN 'opportunity' THEN
      v_tbl := 'opportunities';
      v_col := 'opportunity_number';
    WHEN 'location' THEN
      v_tbl := 'locations';
      v_col := 'location_number';
    WHEN 'person' THEN
      v_tbl := 'persons';
      v_col := 'person_number';
    WHEN 'vendor' THEN
      v_tbl := 'vendors';
      v_col := 'vendor_number';
    WHEN 'schedule' THEN
      v_tbl := 'schedules';
      v_col := 'schedule_number';
    ELSE
      RAISE EXCEPTION 'next_org_scoped_record_number: unknown entity % (expected customer, job, opportunity, location, person, vendor, schedule)', p_entity;
  END CASE;

  EXECUTE format(
    'SELECT COALESCE(MAX(%I), 0::bigint) + 1 FROM public.%I WHERE org_id = $1',
    v_col,
    v_tbl
  )
  INTO v_next
  USING p_org_id;

  RETURN v_next;
END;
$function$

CREATE OR REPLACE FUNCTION public.post_ledger_transaction(p_ledger_tx_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_tx public.ledger_transactions%rowtype;
  v_entry_id uuid;
  v_cash_acct uuid;
  v_clearing_acct uuid;
  v_ar_acct uuid;
  v_rev_acct uuid;
  v_contractor_payable_acct uuid;
  v_contractor_cogs_acct uuid;
  v_fees_acct uuid;
begin
  select * into v_tx
  from public.ledger_transactions
  where id = p_ledger_tx_id;

  if not found then
    raise exception 'ledger tx not found: %', p_ledger_tx_id;
  end if;

  -- idempotent: if already posted, return existing
  if v_tx.journal_entry_id is not null then
    return v_tx.journal_entry_id;
  end if;

  -- required mappings
  select gl_account_id into v_cash_acct
  from public.gl_account_mappings
  where org_id = v_tx.org_id and key = 'cash' and is_active = true;

  select gl_account_id into v_clearing_acct
  from public.gl_account_mappings
  where org_id = v_tx.org_id and key = 'stripe_clearing' and is_active = true;

  select gl_account_id into v_ar_acct
  from public.gl_account_mappings
  where org_id = v_tx.org_id and key = 'accounts_receivable' and is_active = true;

  select gl_account_id into v_rev_acct
  from public.gl_account_mappings
  where org_id = v_tx.org_id and key = 'revenue_gross' and is_active = true;

  select gl_account_id into v_contractor_payable_acct
  from public.gl_account_mappings
  where org_id = v_tx.org_id and key = 'contractor_payable' and is_active = true;

  select gl_account_id into v_contractor_cogs_acct
  from public.gl_account_mappings
  where org_id = v_tx.org_id and key = 'contractor_cogs' and is_active = true;

  select gl_account_id into v_fees_acct
  from public.gl_account_mappings
  where org_id = v_tx.org_id and key = 'processing_fees' and is_active = true;

  if v_cash_acct is null or v_clearing_acct is null or v_ar_acct is null or v_rev_acct is null then
    raise exception 'missing required GL mappings for org %', v_tx.org_id;
  end if;

  -- create journal entry (source = ledger tx)
  insert into public.gl_journal_entries (
    org_id, entry_date, description, status, posted_at, source_type, source_id, metadata
  ) values (
    v_tx.org_id,
    (v_tx.occurred_at at time zone 'utc')::date,
    coalesce(v_tx.metadata->>'description', v_tx.type),
    'posted',
    now(),
    'ledger_transaction',
    v_tx.id,
    jsonb_build_object('ledger_transaction_id', v_tx.id)
  )
  returning id into v_entry_id;

  -- Posting rules (GROSS DEFAULT)
  -- customer_charge (Stripe): Dr Stripe Clearing, Cr Revenue (Gross)
  if v_tx.type = 'customer_charge' then
    insert into public.gl_journal_lines
      (org_id, entry_id, line_no, account_id, debit_cents, credit_cents, currency, job_id, schedule_id, payment_id, customer_id, vendor_id, metadata)
    values
      (v_tx.org_id, v_entry_id, 1, v_clearing_acct, v_tx.amount_cents, 0, v_tx.currency, v_tx.job_id, v_tx.schedule_id, v_tx.payment_id, v_tx.customer_id, v_tx.vendor_id, '{}'::jsonb),
      (v_tx.org_id, v_entry_id, 2, v_rev_acct, 0, v_tx.amount_cents, v_tx.currency, v_tx.job_id, v_tx.schedule_id, v_tx.payment_id, v_tx.customer_id, v_tx.vendor_id, '{}'::jsonb);

  -- contractor_payout: Dr Contractor COGS, Cr Contractor Payable (or Cash if you pay immediately)
  elsif v_tx.type = 'contractor_payout' then
    if v_contractor_payable_acct is null or v_contractor_cogs_acct is null then
      raise exception 'missing contractor mappings (contractor_payable/contractor_cogs) for org %', v_tx.org_id;
    end if;

    insert into public.gl_journal_lines
      (org_id, entry_id, line_no, account_id, debit_cents, credit_cents, currency, job_id, schedule_id, payment_id, customer_id, vendor_id, metadata)
    values
      (v_tx.org_id, v_entry_id, 1, v_contractor_cogs_acct, v_tx.amount_cents, 0, v_tx.currency, v_tx.job_id, v_tx.schedule_id, v_tx.payment_id, v_tx.customer_id, v_tx.vendor_id, '{}'::jsonb),
      (v_tx.org_id, v_entry_id, 2, v_contractor_payable_acct, 0, v_tx.amount_cents, v_tx.currency, v_tx.job_id, v_tx.schedule_id, v_tx.payment_id, v_tx.customer_id, v_tx.vendor_id, '{}'::jsonb);

  -- processing_fee: Dr Processing Fees, Cr Stripe Clearing
  elsif v_tx.type = 'processing_fee' then
    if v_fees_acct is null then
      raise exception 'missing processing_fees mapping for org %', v_tx.org_id;
    end if;

    insert into public.gl_journal_lines
      (org_id, entry_id, line_no, account_id, debit_cents, credit_cents, currency, job_id, schedule_id, payment_id, customer_id, vendor_id, metadata)
    values
      (v_tx.org_id, v_entry_id, 1, v_fees_acct, v_tx.amount_cents, 0, v_tx.currency, v_tx.job_id, v_tx.schedule_id, v_tx.payment_id, v_tx.customer_id, v_tx.vendor_id, '{}'::jsonb),
      (v_tx.org_id, v_entry_id, 2, v_clearing_acct, 0, v_tx.amount_cents, v_tx.currency, v_tx.job_id, v_tx.schedule_id, v_tx.payment_id, v_tx.customer_id, v_tx.vendor_id, '{}'::jsonb);

  else
    raise exception 'unsupported ledger tx type: %', v_tx.type;
  end if;

  -- link ledger tx -> journal entry
  update public.ledger_transactions
  set journal_entry_id = v_entry_id
  where id = v_tx.id;

  return v_entry_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_completed_schedule_history_rewrite()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  -- Only enforce for updates
  if (tg_op <> 'UPDATE') then
    return new;
  end if;

  -- If the OLD row is completed, block historical rewrites
  if (old.status_key = 'completed') then

    -- Block changing assigned_vendor_id
    if (new.assigned_vendor_id is distinct from old.assigned_vendor_id) then
      raise exception 'Cannot change assigned vendor for a completed schedule.';
    end if;

    -- Block changing job_id
    if (new.job_id is distinct from old.job_id) then
      raise exception 'Cannot change job for a completed schedule.';
    end if;

  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.processing_resolve_ref(p_val text, p_refs jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
BEGIN
    IF p_val IS NULL THEN
        RETURN NULL;
    END IF;
    IF left(p_val, 1) = '@' THEN
        RETURN p_refs ->> substring(p_val FROM 2);
    END IF;
    RETURN p_val;
END;
$function$

CREATE OR REPLACE FUNCTION public.ratify_operational_expectation(p_org_id uuid, p_actor_user_id uuid, p_ratification jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_expectation_id uuid := (p_ratification->>'expectation_id')::uuid;
    v_key text := nullif(p_ratification->>'idempotency_key','');
    v_fingerprint text := p_ratification->>'payload_fingerprint';
    v_new public.operational_expectation_ratifications%ROWTYPE;
    v_existing public.operational_expectation_ratifications%ROWTYPE;
    v_mutation_id uuid := gen_random_uuid();
    v_event_id uuid;
    v_exp_authority text; v_exp_subject text; v_exp_modality text; v_exp_standing text;
    v_assignment uuid; v_scope_type text; v_scope_id text;
BEGIN
    IF v_expectation_id IS NULL THEN RAISE EXCEPTION 'oe_ratification_missing_expectation' USING ERRCODE = '22023'; END IF;

    -- Read the expectation's own authority + subject to resolve sufficiency.
    SELECT authority_key, subject_kind, modality, standing INTO v_exp_authority, v_exp_subject, v_exp_modality, v_exp_standing
    FROM public.operational_expectations WHERE id = v_expectation_id AND org_id = p_org_id;
    IF v_exp_authority IS NULL THEN RAISE EXCEPTION 'oe_ratification_expectation_not_found' USING ERRCODE = '23503'; END IF;

    -- AUTHORITY SUFFICIENCY (the ratifier is a human; AI never holds authority).
    v_scope_type := COALESCE(nullif(p_ratification->>'authority_scope_type',''), 'subject_type');
    v_scope_id := COALESCE(nullif(p_ratification->>'authority_scope_id',''), v_exp_subject);
    v_assignment := public.resolve_held_operational_authority(
        p_org_id, 'human', p_actor_user_id::text, v_exp_authority, v_scope_type, v_scope_id, now());
    IF v_assignment IS NULL THEN
        RAISE EXCEPTION 'oe_insufficient_authority' USING ERRCODE = '42501';
    END IF;

    BEGIN
        INSERT INTO public.operational_expectation_ratifications (
            org_id, expectation_id, prior_standing, new_standing, ratifier_authority_key,
            ratified_by_user_id, ratified_by_label, rationale, idempotency_key, payload_fingerprint, metadata
        ) VALUES (
            p_org_id, v_expectation_id, 'proposed', 'binding', v_exp_authority,
            p_actor_user_id, nullif(p_ratification->>'ratified_by_label',''), nullif(p_ratification->>'rationale',''),
            v_key, v_fingerprint, jsonb_build_object('authority_assignment_id', v_assignment, 'matched_scope', v_scope_type)
        ) RETURNING * INTO v_new;

        INSERT INTO public.mutation_events (
            org_id, mutation_id, command_key, domain, subject_id, subject_type,
            previous_state, new_state, operator_id, origin, context_payload, committed_at, effective_at
        ) VALUES (
            p_org_id, v_mutation_id, 'ratify_expectation', 'operational_expectations', v_expectation_id, 'operational_expectation',
            v_new.prior_standing, 'binding', p_actor_user_id::text, 'api',
            jsonb_build_object('ratification_id', v_new.id, 'expectation_id', v_expectation_id, 'authority_key', v_exp_authority,
                'authority_assignment_id', v_assignment, 'matched_scope', v_scope_type, 'prior_standing', v_new.prior_standing,
                'new_standing', 'binding', 'idempotency_key', v_key),
            now(), v_new.ratified_at
        );

        RETURN jsonb_build_object('ok', true, 'disposition', 'created', 'idempotent', false,
            'ratification_id', v_new.id, 'expectation_id', v_expectation_id, 'new_standing', 'binding',
            'authority_assignment_id', v_assignment, 'authoring_act_event_id', v_mutation_id, 'ratified_at', v_new.ratified_at);

    EXCEPTION WHEN unique_violation THEN
        SELECT * INTO v_existing FROM public.operational_expectation_ratifications
        WHERE org_id = p_org_id AND expectation_id = v_expectation_id ORDER BY ratified_at ASC LIMIT 1;
        IF NOT FOUND THEN RAISE; END IF;
        IF v_fingerprint IS NOT NULL AND v_existing.payload_fingerprint IS NOT NULL AND v_existing.payload_fingerprint IS DISTINCT FROM v_fingerprint THEN
            RAISE EXCEPTION 'oe_ratification_conflict' USING ERRCODE = '23505'; END IF;
        SELECT mutation_id INTO v_event_id FROM public.mutation_events
        WHERE org_id = p_org_id AND domain = 'operational_expectations' AND subject_id = v_expectation_id AND command_key = 'ratify_expectation'
        ORDER BY committed_at ASC LIMIT 1;
        RETURN jsonb_build_object('ok', true, 'disposition', 'existing', 'idempotent', true,
            'ratification_id', v_existing.id, 'expectation_id', v_expectation_id, 'new_standing', 'binding',
            'authority_assignment_id', (v_existing.metadata->>'authority_assignment_id'),
            'authoring_act_event_id', COALESCE(v_event_id, v_existing.id), 'ratified_at', v_existing.ratified_at);
    END;
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_consumption_correction(p_org_id uuid, p_actor_user_id uuid, p_plan jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_ce            jsonb := p_plan->'correction_event';
    v_prior_fact_id uuid := NULLIF(p_plan->>'prior_fact_id','')::uuid;
    v_source_family text := v_ce->>'source_family';
    v_prior_event_id uuid;
    v_e1            uuid;
    v_existing_e1   uuid;
    v_obl           jsonb;
    v_charge        jsonb;
    v_reso          text;
    v_obl_id        uuid;
    v_prev_event    uuid;
    v_prev_charge   uuid;
    v_new_charge_id uuid;
    v_new_keys      text[] := ARRAY[]::text[];
    v_reparented    uuid[] := ARRAY[]::uuid[];
    v_upserted      uuid[] := ARRAY[]::uuid[];
    v_superseded    uuid[] := ARRAY[]::uuid[];
    v_retired       uuid[] := ARRAY[]::uuid[];
    v_created_chg   uuid[] := ARRAY[]::uuid[];
    v_orphan        record;
    v_retire_id     text;
    v_chg           uuid;
BEGIN
    -- 1. Lock the prior consumption event by its fact anchor (source_entity_id).
    SELECT id INTO v_prior_event_id
    FROM consumption_events
    WHERE org_id = p_org_id
      AND source_entity_id = v_prior_fact_id
      AND (v_source_family IS NULL OR source_family = v_source_family)
    ORDER BY created_at ASC
    LIMIT 1
    FOR UPDATE;

    IF v_prior_event_id IS NULL THEN
        RAISE EXCEPTION 'reconcile_consumption:no_prior_event';
    END IF;

    -- Lock its obligations (serializes concurrent corrections of this lineage).
    PERFORM 1 FROM resolved_obligations
    WHERE org_id = p_org_id AND consumption_event_id = v_prior_event_id
    FOR UPDATE;

    -- 2. Upsert the correction's OWN consumption event by (org_id, idempotency_key).
    SELECT id INTO v_existing_e1
    FROM consumption_events
    WHERE org_id = p_org_id AND idempotency_key = (v_ce->>'idempotency_key')
    FOR UPDATE;

    IF v_existing_e1 IS NOT NULL THEN
        UPDATE consumption_events SET
            status            = COALESCE(v_ce->>'status', status),
            context           = COALESCE(v_ce->'context', context),
            corrects_event_id = v_prior_event_id,
            updated_by        = p_actor_user_id
        WHERE id = v_existing_e1;
        v_e1 := v_existing_e1;
    ELSE
        INSERT INTO consumption_events (
            org_id, location_id, event_type_id, source_family, event_key,
            source_entity_type, source_entity_id, subject_type, subject_id,
            occurs_on, effective_on, status, context, idempotency_key,
            corrects_event_id, created_by
        ) VALUES (
            p_org_id,
            NULLIF(v_ce->>'location_id','')::uuid,
            NULLIF(v_ce->>'event_type_id','')::uuid,
            v_ce->>'source_family',
            v_ce->>'event_key',
            v_ce->>'source_entity_type',
            (v_ce->>'source_entity_id')::uuid,
            v_ce->>'subject_type',
            NULLIF(v_ce->>'subject_id','')::uuid,
            (v_ce->>'occurs_on')::date,
            NULLIF(v_ce->>'effective_on','')::date,
            COALESCE(v_ce->>'status','resolved'),
            COALESCE(v_ce->'context','{}'::jsonb),
            v_ce->>'idempotency_key',
            v_prior_event_id,
            p_actor_user_id
        ) RETURNING id INTO v_e1;
    END IF;

    -- 3. Reparent + upsert each new obligation by (org_id, resolution_key).
    FOR v_obl IN SELECT * FROM jsonb_array_elements(COALESCE(p_plan->'new_obligations','[]'::jsonb))
    LOOP
        v_reso := v_obl->>'resolution_key';
        v_new_keys := array_append(v_new_keys, v_reso);
        v_charge := v_obl->'charge';
        v_new_charge_id := NULL;

        SELECT id, consumption_event_id, draft_charge_id
        INTO v_obl_id, v_prev_event, v_prev_charge
        FROM resolved_obligations
        WHERE org_id = p_org_id AND resolution_key = v_reso
        FOR UPDATE;

        -- Charge reconciliation is decided UNDER LOCK from the obligation's OWN
        -- draft charge (v_prev_charge, read via the FOR UPDATE above) — never from a
        -- pre-lock plan hint. This is the idempotency parity fix: recalc the live
        -- DRAFT in place, else create one; concurrent same-lineage corrections
        -- therefore converge (the 2nd sees the 1st's draft_charge_id and recalcs it)
        -- and cannot orphan a duplicate draft. The plan carries only PRICED fields
        -- (financials-owned via childcareChargeService); the RPC owns which charge
        -- the reconciliation touches. No pricing here. (Audit F1/F2.)
        IF v_charge IS NOT NULL AND jsonb_typeof(v_charge) = 'object'
           AND NULLIF(v_charge->>'amount_cents','') IS NOT NULL THEN
            v_new_charge_id := NULL;
            IF v_prev_charge IS NOT NULL THEN
                UPDATE charges SET
                    amount_cents = (v_charge->>'amount_cents')::bigint,
                    occurs_on    = NULLIF(v_charge->>'occurs_on','')::date,
                    billable_on  = NULLIF(v_charge->>'billable_on','')::date,
                    service_date = NULLIF(v_charge->>'service_date','')::date,
                    metadata     = COALESCE(v_charge->'metadata', metadata)
                WHERE id = v_prev_charge AND org_id = p_org_id AND status = 'draft';
                IF FOUND THEN
                    v_new_charge_id := v_prev_charge;
                END IF;
            END IF;
            IF v_new_charge_id IS NULL THEN
                INSERT INTO charges (
                    org_id, job_id, billable_source_type, billable_source_id,
                    charge_type, charge_category, status, currency_code, amount_cents,
                    service_date, occurs_on, billable_on, charge_template_id, service_id,
                    description, metadata
                ) VALUES (
                    p_org_id, NULL,
                    COALESCE(v_charge->>'billable_source_type','enrollment_agreement'),
                    NULLIF(v_charge->>'billable_source_id','')::uuid,
                    COALESCE(v_charge->>'charge_type','fee'), v_charge->>'charge_category', 'draft',
                    COALESCE(v_charge->>'currency_code','USD'), (v_charge->>'amount_cents')::bigint,
                    NULLIF(v_charge->>'service_date','')::date, NULLIF(v_charge->>'occurs_on','')::date,
                    NULLIF(v_charge->>'billable_on','')::date, NULLIF(v_charge->>'charge_template_id','')::uuid,
                    NULLIF(v_charge->>'service_id','')::uuid, v_charge->>'description',
                    COALESCE(v_charge->'metadata','{}'::jsonb)
                ) RETURNING id INTO v_new_charge_id;
                v_created_chg := array_append(v_created_chg, v_new_charge_id);
            END IF;
        ELSE
            v_new_charge_id := v_prev_charge;
        END IF;

        IF v_obl_id IS NOT NULL THEN
            UPDATE resolved_obligations SET
                consumption_event_id = v_e1,
                charge_template_id   = NULLIF(v_obl->>'charge_template_id','')::uuid,
                service_id           = NULLIF(v_obl->>'service_id','')::uuid,
                amount_cents         = NULLIF(v_obl->>'amount_cents','')::bigint,
                currency_code        = COALESCE(v_obl->>'currency_code','USD'),
                responsibility_key   = v_obl->>'responsibility_key',
                occurs_on            = NULLIF(v_obl->>'occurs_on','')::date,
                billable_on          = NULLIF(v_obl->>'billable_on','')::date,
                period_start         = NULLIF(v_obl->>'period_start','')::date,
                period_end           = NULLIF(v_obl->>'period_end','')::date,
                status               = COALESCE(v_obl->>'status', status),
                review_required      = COALESCE((v_obl->>'review_required')::boolean, review_required),
                explanation          = COALESCE(v_obl->'explanation', explanation),
                obligation_kind      = v_obl->>'obligation_kind',
                draft_charge_id      = v_new_charge_id,
                superseded_by_event_id = NULL,
                review_status        = CASE WHEN (v_obl->>'review_status_stale')::boolean IS TRUE
                                            THEN 'stale' ELSE review_status END,
                updated_by           = p_actor_user_id
            WHERE id = v_obl_id;
            IF v_prev_event IS DISTINCT FROM v_e1 THEN
                v_reparented := array_append(v_reparented, v_obl_id);
            END IF;
            v_upserted := array_append(v_upserted, v_obl_id);
        ELSE
            INSERT INTO resolved_obligations (
                org_id, consumption_event_id, charge_template_id, service_id,
                amount_cents, currency_code, responsibility_key, occurs_on, billable_on,
                period_start, period_end, status, review_required, explanation,
                draft_charge_id, resolution_key, obligation_kind, review_status, created_by
            ) VALUES (
                p_org_id, v_e1, NULLIF(v_obl->>'charge_template_id','')::uuid,
                NULLIF(v_obl->>'service_id','')::uuid, NULLIF(v_obl->>'amount_cents','')::bigint,
                COALESCE(v_obl->>'currency_code','USD'), v_obl->>'responsibility_key',
                NULLIF(v_obl->>'occurs_on','')::date, NULLIF(v_obl->>'billable_on','')::date,
                NULLIF(v_obl->>'period_start','')::date, NULLIF(v_obl->>'period_end','')::date,
                COALESCE(v_obl->>'status','previewed'), COALESCE((v_obl->>'review_required')::boolean, false),
                COALESCE(v_obl->'explanation','{}'::jsonb), v_new_charge_id, v_reso,
                v_obl->>'obligation_kind',
                CASE WHEN COALESCE((v_obl->>'review_required')::boolean,false) THEN 'review_required' ELSE 'pending' END,
                p_actor_user_id
            ) RETURNING id INTO v_obl_id;
            v_upserted := array_append(v_upserted, v_obl_id);
        END IF;
    END LOOP;

    -- 4. Supersede orphans: prior obligations whose resolution_key is absent from
    --    the corrected pass. Collect their draft charges for retirement.
    FOR v_orphan IN
        SELECT id, resolution_key, draft_charge_id
        FROM resolved_obligations
        WHERE org_id = p_org_id
          AND consumption_event_id = v_prior_event_id
          AND (resolution_key IS NULL OR NOT (resolution_key = ANY (v_new_keys)))
    LOOP
        UPDATE resolved_obligations SET
            status                 = 'superseded',
            superseded_by_event_id = v_e1,
            review_status          = 'stale',
            updated_by             = p_actor_user_id
        WHERE id = v_orphan.id;
        v_superseded := array_append(v_superseded, v_orphan.id);
        IF v_orphan.draft_charge_id IS NOT NULL THEN
            v_retired := array_append(v_retired, v_orphan.draft_charge_id);
        END IF;
    END LOOP;

    -- Union in any explicitly-planned retire ids (idempotent; draft-only guard).
    IF p_plan->'retire_charge_ids' IS NOT NULL THEN
        FOR v_retire_id IN SELECT jsonb_array_elements_text(p_plan->'retire_charge_ids')
        LOOP
            IF NOT (v_retire_id::uuid = ANY (v_retired)) THEN
                v_retired := array_append(v_retired, v_retire_id::uuid);
            END IF;
        END LOOP;
    END IF;

    -- 5. Retire draft charges in place (draft -> void). Posted/non-draft => 0 rows.
    FOREACH v_chg IN ARRAY v_retired
    LOOP
        UPDATE charges SET
            status    = 'void',
            voided_at = now(),
            metadata  = COALESCE(metadata,'{}'::jsonb) || jsonb_build_object(
                'retirement', jsonb_build_object(
                    'reason', 'obligation_superseded',
                    'actor_user_id', p_actor_user_id,
                    'superseded_by_consumption_event_id', v_e1,
                    'retired_at', now()
                ))
        WHERE id = v_chg
          AND org_id = p_org_id
          AND billable_source_type = 'enrollment_agreement'
          AND status = 'draft';
    END LOOP;

    -- 6. Retire the prior event.
    UPDATE consumption_events SET status = 'superseded', updated_by = p_actor_user_id
    WHERE id = v_prior_event_id AND org_id = p_org_id;

    RETURN jsonb_build_object(
        'ok', true,
        'consumption_event_id', v_e1,
        'prior_consumption_event_id', v_prior_event_id,
        'obligation_ids', to_jsonb(v_upserted),
        'reparented_obligation_ids', to_jsonb(v_reparented),
        'superseded_obligation_ids', to_jsonb(v_superseded),
        'retired_charge_ids', to_jsonb(v_retired),
        'created_charge_ids', to_jsonb(v_created_chg)
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.revoke_operational_authority_assignment(p_org_id uuid, p_assignment_id uuid, p_actor uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_auth text; v_ht text; v_hid text; v_st text; v_sid text;
BEGIN
    SELECT authority_key, holder_type, holder_id, scope_type, scope_id INTO v_auth, v_ht, v_hid, v_st, v_sid
    FROM public.operational_authority_assignments WHERE id = p_assignment_id AND org_id = p_org_id AND status = 'granted';
    IF v_auth IS NULL THEN RAISE EXCEPTION 'oe_authority_assignment: grant % not found in org', p_assignment_id USING ERRCODE = '23503'; END IF;
    INSERT INTO public.operational_authority_assignments
        (org_id, authority_key, holder_type, holder_id, scope_type, scope_id, status, supersedes_assignment_id, granted_by)
    VALUES (p_org_id, v_auth, v_ht, v_hid, v_st, v_sid, 'revoked', p_assignment_id, p_actor)
    RETURNING id INTO v_id;
    RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.scaled_base_cents(old_dollars numeric)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare
  scaled numeric;
  cents int;
begin
  scaled := old_dollars * (200.0 / 180.0);
  cents := (scaled * 100)::int;
  return public.round_to_nearest_5_cents(cents);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_person_full_name()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.full_name := nullif(trim(concat_ws(' ', new.first_name, new.last_name)), '');
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_program_offering_variants_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_program_offerings_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at_opportunities()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    new_wo jsonb;
    old_wo jsonb;
BEGIN
    new_wo := to_jsonb(NEW) - 'metadata' - 'updated_at';
    old_wo := to_jsonb(OLD) - 'metadata' - 'updated_at';

    IF NEW.metadata IS DISTINCT FROM OLD.metadata AND new_wo IS NOT DISTINCT FROM old_wo THEN
        NEW.updated_at := OLD.updated_at;
        RETURN NEW;
    END IF;

    NEW.updated_at := now();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_communication_template_version_legacy()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.version_number IS NOT NULL AND (NEW.version IS NULL OR NEW.version <> NEW.version_number) THEN
        NEW.version := NEW.version_number;
    ELSIF NEW.version IS NOT NULL AND NEW.version_number IS NULL THEN
        NEW.version_number := NEW.version;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_form_definition_versions_org_id()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    p_org uuid;
BEGIN
    SELECT fd.org_id INTO p_org
    FROM public.form_definitions fd
    WHERE fd.id = NEW.form_definition_id;
    IF p_org IS NULL THEN
        RAISE EXCEPTION 'form_definition_versions: form_definition_id % not found', NEW.form_definition_id;
    END IF;
    IF NEW.org_id IS NOT NULL AND NEW.org_id <> p_org THEN
        RAISE EXCEPTION 'form_definition_versions: org_id must match form_definitions.org_id';
    END IF;
    NEW.org_id := p_org;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_form_packet_items_org_from_packet()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    p_org uuid;
BEGIN
    SELECT fpd.org_id INTO p_org
    FROM public.form_packet_definitions fpd
    WHERE fpd.id = NEW.packet_definition_id;
    IF p_org IS NULL THEN
        RAISE EXCEPTION 'form_packet_items: packet_definition_id % not found', NEW.packet_definition_id;
    END IF;
    IF NEW.org_id IS NOT NULL AND NEW.org_id <> p_org THEN
        RAISE EXCEPTION 'form_packet_items: org_id must match form_packet_definitions.org_id';
    END IF;
    NEW.org_id := p_org;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_form_packet_session_items_org_from_session()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    o uuid;
BEGIN
    SELECT fps.org_id INTO o FROM public.form_packet_sessions fps WHERE fps.id = NEW.packet_session_id;
    IF o IS NULL THEN
        RAISE EXCEPTION 'form_packet_session_items: packet_session_id not found';
    END IF;
    NEW.org_id := o;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_form_packet_sessions_org_from_packet_def()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    p_org uuid;
BEGIN
    SELECT fpd.org_id INTO p_org
    FROM public.form_packet_definitions fpd
    WHERE fpd.id = NEW.packet_definition_id;
    IF p_org IS NULL THEN
        RAISE EXCEPTION 'form_packet_sessions: packet_definition_id not found';
    END IF;
    IF NEW.org_id IS NOT NULL AND NEW.org_id <> p_org THEN
        RAISE EXCEPTION 'form_packet_sessions: org_id must match packet definition org';
    END IF;
    NEW.org_id := p_org;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_form_public_links_org_from_definition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    p_org uuid;
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.form_definition_id IS NOT DISTINCT FROM OLD.form_definition_id THEN
        RETURN NEW;
    END IF;
    SELECT fd.org_id INTO p_org FROM public.form_definitions fd WHERE fd.id = NEW.form_definition_id;
    IF p_org IS NULL THEN
        RAISE EXCEPTION 'form_public_links: form_definition_id invalid';
    END IF;
    NEW.org_id := p_org;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_form_submission_documents_org_from_submission()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    o uuid;
BEGIN
    SELECT fs.org_id INTO o FROM public.form_submissions fs WHERE fs.id = NEW.form_submission_id;
    IF o IS NULL THEN
        RAISE EXCEPTION 'form_submission_documents: submission % not found', NEW.form_submission_id;
    END IF;
    NEW.org_id := o;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_form_submission_signatures_org_from_submission()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    o uuid;
BEGIN
    SELECT fs.org_id INTO o FROM public.form_submissions fs WHERE fs.id = NEW.form_submission_id;
    IF o IS NULL THEN
        RAISE EXCEPTION 'form_submission_signatures: submission % not found', NEW.form_submission_id;
    END IF;
    NEW.org_id := o;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_form_submissions_org_and_definition_from_version()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    vid uuid := NEW.form_definition_version_id;
    v_def uuid;
    v_org uuid;
    link_org uuid;
BEGIN
    SELECT v.form_definition_id, v.org_id INTO v_def, v_org
    FROM public.form_definition_versions v
    WHERE v.id = vid;
    IF v_def IS NULL THEN
        RAISE EXCEPTION 'form_submissions: form_definition_version_id % not found', vid;
    END IF;
    IF NEW.form_definition_id IS NOT NULL AND NEW.form_definition_id <> v_def THEN
        RAISE EXCEPTION 'form_submissions: form_definition_id must match version.form_definition_id';
    END IF;
    NEW.form_definition_id := v_def;
    NEW.org_id := v_org;

    -- Run after org_id is authoritative (ordering-safe vs separate triggers)
    IF NEW.created_via_public_link_id IS NOT NULL THEN
        SELECT fpl.org_id INTO link_org FROM public.form_public_links fpl WHERE fpl.id = NEW.created_via_public_link_id;
        IF link_org IS NULL THEN
            RAISE EXCEPTION 'form_submissions: created_via_public_link_id not found';
        END IF;
        IF link_org <> NEW.org_id THEN
            RAISE EXCEPTION 'form_submissions: public link org_id must match submission org_id';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_assign_org_scoped_record_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  CASE TG_TABLE_NAME::text
    WHEN 'persons' THEN
      IF NEW.person_number IS NULL THEN
        IF NEW.org_id IS NULL THEN
          RAISE EXCEPTION 'persons: org_id is required when person_number is omitted';
        END IF;
        NEW.person_number := public.next_org_scoped_record_number(NEW.org_id, 'person');
      END IF;

    WHEN 'customers' THEN
      IF NEW.customer_number IS NULL THEN
        IF NEW.org_id IS NULL THEN
          RAISE EXCEPTION 'customers: org_id is required when customer_number is omitted';
        END IF;
        NEW.customer_number := public.next_org_scoped_record_number(NEW.org_id, 'customer');
      END IF;

    WHEN 'jobs' THEN
      IF NEW.job_number IS NULL THEN
        IF NEW.org_id IS NULL THEN
          RAISE EXCEPTION 'jobs: org_id is required when job_number is omitted';
        END IF;
        NEW.job_number := public.next_org_scoped_record_number(NEW.org_id, 'job');
      END IF;

    WHEN 'opportunities' THEN
      IF NEW.opportunity_number IS NULL THEN
        IF NEW.org_id IS NULL THEN
          RAISE EXCEPTION 'opportunities: org_id is required when opportunity_number is omitted';
        END IF;
        NEW.opportunity_number := public.next_org_scoped_record_number(NEW.org_id, 'opportunity');
      END IF;

    WHEN 'locations' THEN
      IF NEW.location_number IS NULL THEN
        IF NEW.org_id IS NULL THEN
          RAISE EXCEPTION 'locations: org_id is required when location_number is omitted';
        END IF;
        NEW.location_number := public.next_org_scoped_record_number(NEW.org_id, 'location');
      END IF;

    WHEN 'vendors' THEN
      IF NEW.vendor_number IS NULL THEN
        IF NEW.org_id IS NULL THEN
          RAISE EXCEPTION 'vendors: org_id is required when vendor_number is omitted';
        END IF;
        NEW.vendor_number := public.next_org_scoped_record_number(NEW.org_id, 'vendor');
      END IF;

    WHEN 'schedules' THEN
      IF NEW.schedule_number IS NULL THEN
        IF NEW.org_id IS NULL THEN
          RAISE EXCEPTION 'schedules: org_id is required when schedule_number is omitted';
        END IF;
        NEW.schedule_number := public.next_org_scoped_record_number(NEW.org_id, 'schedule');
      END IF;

    ELSE
      RAISE EXCEPTION 'trg_assign_org_scoped_record_number: unexpected table %', TG_TABLE_NAME::text;
  END CASE;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_jobs_assign_pricing_tier()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_completed_count integer;
  v_job_number integer;
  v_contractor_bps integer;
  v_alloy_bps integer;
  v_gross integer;
begin
  -- Require customer_id + vertical_id to compute tier
  if new.customer_id is null or new.vertical_id is null then
    return new;
  end if;

  -- Ensure a counter row exists
  insert into public.customer_vertical_job_counters (customer_id, vertical_id, completed_count)
  values (new.customer_id, new.vertical_id, 0)
  on conflict (customer_id, vertical_id) do nothing;

  select completed_count
    into v_completed_count
  from public.customer_vertical_job_counters
  where customer_id = new.customer_id
    and vertical_id = new.vertical_id;

  -- Job number is "next" based on completed count
  v_job_number := coalesce(v_completed_count, 0) + 1;

  -- Only set job_number if not provided explicitly
  if new.job_number_for_customer is null then
    new.job_number_for_customer := v_job_number;
  end if;

  -- Compute split from job_number
  select contractor_bps, alloy_bps
    into v_contractor_bps, v_alloy_bps
  from public.fn_job_split_bps(new.job_number_for_customer);

  new.contractor_split_bps := v_contractor_bps;
  new.alloy_split_bps := v_alloy_bps;

  -- Determine gross price for payout math:
  -- prefer gross_price_cents if provided, else fall back to estimated_total_cents.
  v_gross := coalesce(new.gross_price_cents, new.estimated_total_cents);

  if v_gross is not null then
    new.gross_price_cents := v_gross;

    -- Integer math (round down cents)
    new.contractor_payout_cents := (v_gross * v_contractor_bps) / 10000;
    new.alloy_fee_cents := v_gross - new.contractor_payout_cents;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_post_payment_to_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.posted_to_ledger_at is not null then
    return new;
  end if;

  if (new.posted_at is not null)
     and (old.posted_at is distinct from new.posted_at)
  then
    perform public.post_payment_to_ledger(new.id);
    return new;
  end if;

  if (new.paid_at is not null)
     and (old.paid_at is distinct from new.paid_at)
  then
    perform public.post_payment_to_ledger(new.id);
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_child_attendance_events_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    agr_org uuid;
    agr_member uuid;
    agr_site uuid;
    site_org uuid;
    site_type text;
    r_org uuid;
    r_type text;
    r_parent uuid;
    c_org uuid;
    c_agreement uuid;
BEGIN
    SELECT a.org_id, a.customer_member_id, a.site_location_id
    INTO agr_org, agr_member, agr_site
    FROM public.child_enrollment_agreements a
    WHERE a.id = NEW.enrollment_agreement_id;

    IF agr_org IS NULL THEN
        RAISE EXCEPTION 'child_attendance_events: enrollment_agreement_id % not found', NEW.enrollment_agreement_id
            USING ERRCODE = '23503';
    END IF;
    IF agr_org <> NEW.org_id THEN
        RAISE EXCEPTION 'child_attendance_events: agreement org mismatch' USING ERRCODE = '23514';
    END IF;
    IF agr_member <> NEW.customer_member_id THEN
        RAISE EXCEPTION 'child_attendance_events: customer_member_id does not match agreement' USING ERRCODE = '23514';
    END IF;
    IF NEW.site_location_id <> agr_site THEN
        RAISE EXCEPTION 'child_attendance_events: site_location_id must match agreement site' USING ERRCODE = '23514';
    END IF;

    SELECT l.org_id, l.location_type INTO site_org, site_type
    FROM public.locations l WHERE l.id = NEW.site_location_id;
    IF site_org IS NULL OR site_org <> NEW.org_id OR site_type IS DISTINCT FROM 'site' THEN
        RAISE EXCEPTION 'child_attendance_events: invalid site_location_id %', NEW.site_location_id USING ERRCODE = '23514';
    END IF;

    -- Any referenced room must be a unit under the agreement site.
    IF NEW.room_location_id IS NOT NULL OR NEW.from_room_location_id IS NOT NULL OR NEW.to_room_location_id IS NOT NULL THEN
        FOR r_org, r_type, r_parent IN
            SELECT l.org_id, l.location_type, l.parent_location_id
            FROM public.locations l
            WHERE l.id = ANY (ARRAY[NEW.room_location_id, NEW.from_room_location_id, NEW.to_room_location_id])
        LOOP
            IF r_org IS DISTINCT FROM NEW.org_id OR r_type IS DISTINCT FROM 'unit' THEN
                RAISE EXCEPTION 'child_attendance_events: room must be a unit in the same org' USING ERRCODE = '23514';
            END IF;
            IF r_parent IS DISTINCT FROM NEW.site_location_id THEN
                RAISE EXCEPTION 'child_attendance_events: room must be a child of the agreement site' USING ERRCODE = '23514';
            END IF;
        END LOOP;
    END IF;

    -- Correction/reversal target must be a prior event in the same org + agreement.
    IF NEW.corrects_event_id IS NOT NULL THEN
        SELECT e.org_id, e.enrollment_agreement_id INTO c_org, c_agreement
        FROM public.child_attendance_events e WHERE e.id = NEW.corrects_event_id;
        IF c_org IS NULL THEN
            RAISE EXCEPTION 'child_attendance_events: corrects_event_id % not found', NEW.corrects_event_id USING ERRCODE = '23503';
        END IF;
        IF c_org <> NEW.org_id OR c_agreement <> NEW.enrollment_agreement_id THEN
            RAISE EXCEPTION 'child_attendance_events: correction must target an event on the same org and agreement' USING ERRCODE = '23514';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_child_enrollment_agreements_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    opp_org uuid;
    opp_customer uuid;
    ocm_org uuid;
    ocm_opp uuid;
    ocm_member uuid;
    mem_org uuid;
    mem_customer uuid;
    mem_person uuid;
    person_org uuid;
    site_org uuid;
    site_type text;
BEGIN
    SELECT cm.org_id, cm.customer_id, cm.person_id
    INTO mem_org, mem_customer, mem_person
    FROM public.customer_members cm
    WHERE cm.id = NEW.customer_member_id;

    IF mem_org IS NULL THEN
        RAISE EXCEPTION 'child_enrollment_agreements: customer_member_id % not found', NEW.customer_member_id
            USING ERRCODE = '23503';
    END IF;
    IF mem_org <> NEW.org_id THEN
        RAISE EXCEPTION 'child_enrollment_agreements: customer_member org mismatch'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.customer_id IS NULL THEN
        NEW.customer_id := mem_customer;
    ELSIF NEW.customer_id <> mem_customer THEN
        RAISE EXCEPTION 'child_enrollment_agreements: customer_id does not match customer_member'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.person_id IS NULL THEN
        NEW.person_id := mem_person;
    ELSIF NEW.person_id IS DISTINCT FROM mem_person THEN
        RAISE EXCEPTION 'child_enrollment_agreements: person_id does not match customer_member'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.opportunity_id IS NOT NULL THEN
        SELECT o.org_id, o.customer_id
        INTO opp_org, opp_customer
        FROM public.opportunities o
        WHERE o.id = NEW.opportunity_id;

        IF opp_org IS NULL THEN
            RAISE EXCEPTION 'child_enrollment_agreements: opportunity_id % not found', NEW.opportunity_id
                USING ERRCODE = '23503';
        END IF;
        IF opp_org <> NEW.org_id THEN
            RAISE EXCEPTION 'child_enrollment_agreements: opportunity org mismatch'
                USING ERRCODE = '23514';
        END IF;
        IF NEW.customer_id IS NOT NULL AND opp_customer IS NOT NULL AND NEW.customer_id <> opp_customer THEN
            RAISE EXCEPTION 'child_enrollment_agreements: opportunity customer mismatch'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NEW.opportunity_customer_member_id IS NOT NULL THEN
        SELECT ocm.org_id, ocm.opportunity_id, ocm.customer_member_id
        INTO ocm_org, ocm_opp, ocm_member
        FROM public.opportunity_customer_members ocm
        WHERE ocm.id = NEW.opportunity_customer_member_id;

        IF ocm_org IS NULL THEN
            RAISE EXCEPTION 'child_enrollment_agreements: opportunity_customer_member_id % not found',
                NEW.opportunity_customer_member_id
                USING ERRCODE = '23503';
        END IF;
        IF ocm_org <> NEW.org_id THEN
            RAISE EXCEPTION 'child_enrollment_agreements: OCM org mismatch'
                USING ERRCODE = '23514';
        END IF;
        IF NEW.opportunity_id IS NOT NULL AND ocm_opp <> NEW.opportunity_id THEN
            RAISE EXCEPTION 'child_enrollment_agreements: OCM opportunity mismatch'
                USING ERRCODE = '23514';
        END IF;
        IF ocm_member <> NEW.customer_member_id THEN
            RAISE EXCEPTION 'child_enrollment_agreements: OCM customer_member mismatch'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    SELECT l.org_id, l.location_type
    INTO site_org, site_type
    FROM public.locations l
    WHERE l.id = NEW.site_location_id;

    IF site_org IS NULL THEN
        RAISE EXCEPTION 'child_enrollment_agreements: site_location_id % not found', NEW.site_location_id
            USING ERRCODE = '23503';
    END IF;
    IF site_org <> NEW.org_id THEN
        RAISE EXCEPTION 'child_enrollment_agreements: site org mismatch'
            USING ERRCODE = '23514';
    END IF;
    IF site_type IS DISTINCT FROM 'site' THEN
        RAISE EXCEPTION 'child_enrollment_agreements: site_location_id % must be location_type site (got %)',
            NEW.site_location_id, site_type
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_child_placements_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    agr_org uuid;
    agr_member uuid;
    agr_site uuid;
    site_org uuid;
    site_type text;
    room_org uuid;
    room_type text;
    room_parent uuid;
    prog_org uuid;
    prog_site uuid;
BEGIN
    SELECT a.org_id, a.customer_member_id, a.site_location_id
    INTO agr_org, agr_member, agr_site
    FROM public.child_enrollment_agreements a
    WHERE a.id = NEW.enrollment_agreement_id;

    IF agr_org IS NULL THEN
        RAISE EXCEPTION 'child_placements: enrollment_agreement_id % not found', NEW.enrollment_agreement_id
            USING ERRCODE = '23503';
    END IF;
    IF agr_org <> NEW.org_id THEN
        RAISE EXCEPTION 'child_placements: agreement org mismatch'
            USING ERRCODE = '23514';
    END IF;
    IF agr_member <> NEW.customer_member_id THEN
        RAISE EXCEPTION 'child_placements: customer_member_id does not match agreement'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.site_location_id <> agr_site THEN
        RAISE EXCEPTION 'child_placements: site_location_id must match agreement site'
            USING ERRCODE = '23514';
    END IF;

    SELECT l.org_id, l.location_type
    INTO site_org, site_type
    FROM public.locations l
    WHERE l.id = NEW.site_location_id;

    IF site_org IS NULL OR site_org <> NEW.org_id OR site_type IS DISTINCT FROM 'site' THEN
        RAISE EXCEPTION 'child_placements: invalid site_location_id %', NEW.site_location_id
            USING ERRCODE = '23514';
    END IF;

    IF NEW.program_category_id IS NOT NULL THEN
        SELECT lpc.org_id, lpc.location_id
        INTO prog_org, prog_site
        FROM public.location_program_categories lpc
        WHERE lpc.id = NEW.program_category_id;

        IF prog_org IS NULL THEN
            RAISE EXCEPTION 'child_placements: program_category_id % not found', NEW.program_category_id
                USING ERRCODE = '23503';
        END IF;
        IF prog_org <> NEW.org_id OR prog_site <> NEW.site_location_id THEN
            RAISE EXCEPTION 'child_placements: program_category must belong to placement site'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NEW.room_location_id IS NOT NULL THEN
        SELECT l.org_id, l.location_type, l.parent_location_id
        INTO room_org, room_type, room_parent
        FROM public.locations l
        WHERE l.id = NEW.room_location_id;

        IF room_org IS NULL THEN
            RAISE EXCEPTION 'child_placements: room_location_id % not found', NEW.room_location_id
                USING ERRCODE = '23503';
        END IF;
        IF room_org <> NEW.org_id OR room_type IS DISTINCT FROM 'unit' THEN
            RAISE EXCEPTION 'child_placements: room_location_id % must be location_type unit', NEW.room_location_id
                USING ERRCODE = '23514';
        END IF;
        IF room_parent IS DISTINCT FROM NEW.site_location_id THEN
            RAISE EXCEPTION 'child_placements: room % must be child of site %',
                NEW.room_location_id, NEW.site_location_id
                USING ERRCODE = '23514';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_childcare_config_scope()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    site_org uuid;
    site_type text;
    prog_org uuid;
    room_org uuid;
    room_type text;
    room_parent uuid;
BEGIN
    IF NEW.site_location_id IS NOT NULL THEN
        SELECT l.org_id, l.location_type INTO site_org, site_type
        FROM public.locations l WHERE l.id = NEW.site_location_id;
        IF site_org IS NULL THEN
            RAISE EXCEPTION 'childcare config scope: site_location_id % not found', NEW.site_location_id
                USING ERRCODE = '23503';
        END IF;
        IF site_org <> NEW.org_id THEN
            RAISE EXCEPTION 'childcare config scope: site org mismatch' USING ERRCODE = '23514';
        END IF;
        IF site_type IS DISTINCT FROM 'site' THEN
            RAISE EXCEPTION 'childcare config scope: site_location_id % must be location_type site (got %)',
                NEW.site_location_id, site_type USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NEW.program_category_id IS NOT NULL THEN
        SELECT lpc.org_id INTO prog_org
        FROM public.location_program_categories lpc WHERE lpc.id = NEW.program_category_id;
        IF prog_org IS NULL THEN
            RAISE EXCEPTION 'childcare config scope: program_category_id % not found', NEW.program_category_id
                USING ERRCODE = '23503';
        END IF;
        IF prog_org <> NEW.org_id THEN
            RAISE EXCEPTION 'childcare config scope: program category org mismatch' USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NEW.room_location_id IS NOT NULL THEN
        SELECT l.org_id, l.location_type, l.parent_location_id
        INTO room_org, room_type, room_parent
        FROM public.locations l WHERE l.id = NEW.room_location_id;
        IF room_org IS NULL THEN
            RAISE EXCEPTION 'childcare config scope: room_location_id % not found', NEW.room_location_id
                USING ERRCODE = '23503';
        END IF;
        IF room_org <> NEW.org_id THEN
            RAISE EXCEPTION 'childcare config scope: room org mismatch' USING ERRCODE = '23514';
        END IF;
        IF room_type IS DISTINCT FROM 'unit' THEN
            RAISE EXCEPTION 'childcare config scope: room_location_id % must be location_type unit (got %)',
                NEW.room_location_id, room_type USING ERRCODE = '23514';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_childcare_rate_rule()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    plan_org uuid;
BEGIN
    SELECT p.org_id INTO plan_org
    FROM public.childcare_rate_plans p WHERE p.id = NEW.rate_plan_id;
    IF plan_org IS NULL THEN
        RAISE EXCEPTION 'childcare rate rule: rate_plan_id % not found', NEW.rate_plan_id
            USING ERRCODE = '23503';
    END IF;
    IF plan_org <> NEW.org_id THEN
        RAISE EXCEPTION 'childcare rate rule: org_id must match parent rate plan org' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_financial_policy_scope()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    loc_org uuid;
    svc_org uuid;
    plan_org uuid;
BEGIN
    IF NEW.location_id IS NOT NULL THEN
        SELECT l.org_id INTO loc_org FROM public.locations l WHERE l.id = NEW.location_id;
        IF loc_org IS NULL THEN
            RAISE EXCEPTION 'financial policy scope: location_id % not found', NEW.location_id USING ERRCODE = '23503';
        END IF;
        IF loc_org <> NEW.org_id THEN
            RAISE EXCEPTION 'financial policy scope: location org mismatch' USING ERRCODE = '23514';
        END IF;
    END IF;
    IF NEW.service_id IS NOT NULL THEN
        SELECT s.org_id INTO svc_org FROM public.financial_services s WHERE s.id = NEW.service_id;
        IF svc_org IS NULL THEN
            RAISE EXCEPTION 'financial policy scope: service_id % not found', NEW.service_id USING ERRCODE = '23503';
        END IF;
        IF svc_org <> NEW.org_id THEN
            RAISE EXCEPTION 'financial policy scope: service org mismatch' USING ERRCODE = '23514';
        END IF;
    END IF;
    IF NEW.rate_plan_id IS NOT NULL THEN
        SELECT p.org_id INTO plan_org FROM public.childcare_rate_plans p WHERE p.id = NEW.rate_plan_id;
        IF plan_org IS NULL THEN
            RAISE EXCEPTION 'financial policy scope: rate_plan_id % not found', NEW.rate_plan_id USING ERRCODE = '23503';
        END IF;
        IF plan_org <> NEW.org_id THEN
            RAISE EXCEPTION 'financial policy scope: rate plan org mismatch' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_form_packet_items_form_org()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    def_org uuid;
    ver_form uuid;
    ver_org uuid;
BEGIN
    SELECT fd.org_id INTO def_org FROM public.form_definitions fd WHERE fd.id = NEW.form_definition_id;
    IF def_org IS NULL THEN
        RAISE EXCEPTION 'form_packet_items: form_definition_id % not found', NEW.form_definition_id;
    END IF;
    IF def_org <> NEW.org_id THEN
        RAISE EXCEPTION 'form_packet_items: form_definition must belong to same org as packet';
    END IF;

    IF NEW.pinned_form_definition_version_id IS NOT NULL THEN
        SELECT v.form_definition_id, v.org_id INTO ver_form, ver_org
        FROM public.form_definition_versions v
        WHERE v.id = NEW.pinned_form_definition_version_id;
        IF ver_form IS NULL THEN
            RAISE EXCEPTION 'form_packet_items: pinned_form_definition_version_id not found';
        END IF;
        IF ver_form <> NEW.form_definition_id THEN
            RAISE EXCEPTION 'form_packet_items: pinned version must match form_definition_id';
        END IF;
        IF ver_org <> NEW.org_id THEN
            RAISE EXCEPTION 'form_packet_items: pinned version org mismatch';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_form_packet_session_items_packet_match()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    sess_def uuid;
    item_def uuid;
BEGIN
    SELECT fps.packet_definition_id INTO sess_def FROM public.form_packet_sessions fps WHERE fps.id = NEW.packet_session_id;
    SELECT fpi.packet_definition_id INTO item_def FROM public.form_packet_items fpi WHERE fpi.id = NEW.packet_item_id;
    IF sess_def IS DISTINCT FROM item_def THEN
        RAISE EXCEPTION 'form_packet_session_items: packet_item does not belong to session packet_definition';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_form_packet_session_items_submission_org()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    sub_org uuid;
BEGIN
    IF NEW.form_submission_id IS NULL THEN
        RETURN NEW;
    END IF;
    SELECT fs.org_id INTO sub_org FROM public.form_submissions fs WHERE fs.id = NEW.form_submission_id;
    IF sub_org IS NULL THEN
        RAISE EXCEPTION 'form_packet_session_items: form_submission_id not found';
    END IF;
    IF sub_org <> NEW.org_id THEN
        RAISE EXCEPTION 'form_packet_session_items: submission org_id mismatch';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_form_packet_sessions_link_org()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    link_org uuid;
BEGIN
    SELECT fpl.org_id INTO link_org FROM public.form_public_links fpl WHERE fpl.id = NEW.started_via_public_link_id;
    IF link_org IS NULL THEN
        RAISE EXCEPTION 'form_packet_sessions: started_via_public_link_id not found';
    END IF;
    IF link_org <> NEW.org_id THEN
        RAISE EXCEPTION 'form_packet_sessions: link org_id must match session org_id';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_form_public_links_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    def_org uuid;
    ver_form uuid;
    ver_org uuid;
BEGIN
    SELECT fd.org_id INTO def_org
    FROM public.form_definitions fd
    WHERE fd.id = NEW.form_definition_id;
    IF def_org IS NULL THEN
        RAISE EXCEPTION 'form_public_links: form_definition_id % not found', NEW.form_definition_id;
    END IF;
    IF def_org <> NEW.org_id THEN
        RAISE EXCEPTION 'form_public_links: org_id must match form_definitions.org_id';
    END IF;

    IF NEW.pinned_form_definition_version_id IS NOT NULL THEN
        SELECT v.form_definition_id, v.org_id INTO ver_form, ver_org
        FROM public.form_definition_versions v
        WHERE v.id = NEW.pinned_form_definition_version_id;

        IF ver_form IS NULL THEN
            RAISE EXCEPTION 'form_public_links: pinned_form_definition_version_id % not found', NEW.pinned_form_definition_version_id;
        END IF;
        IF ver_form <> NEW.form_definition_id THEN
            RAISE EXCEPTION 'form_public_links: pinned version must belong to same form_definition_id';
        END IF;
        IF ver_org <> NEW.org_id THEN
            RAISE EXCEPTION 'form_public_links: pinned version org_id mismatch';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_form_submission_documents_org_matches_document()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    row_org uuid;
    doc_org uuid;
BEGIN
    SELECT fs.org_id INTO row_org FROM public.form_submissions fs WHERE fs.id = NEW.form_submission_id;
    SELECT d.org_id INTO doc_org FROM public.documents d WHERE d.id = NEW.document_id;
    IF doc_org IS NULL THEN
        RAISE EXCEPTION 'form_submission_documents: document_id % not found', NEW.document_id;
    END IF;
    IF doc_org <> row_org THEN
        RAISE EXCEPTION 'form_submission_documents: document.org_id must match submission.org_id';
    END IF;
    IF NEW.org_id <> row_org THEN
        RAISE EXCEPTION 'form_submission_documents: org_id must match submission';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_form_submission_signatures_drawn_asset_org()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    row_org uuid;
    doc_org uuid;
BEGIN
    IF NEW.drawn_asset_document_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT fs.org_id INTO row_org FROM public.form_submissions fs WHERE fs.id = NEW.form_submission_id;
    SELECT d.org_id INTO doc_org FROM public.documents d WHERE d.id = NEW.drawn_asset_document_id;
    IF doc_org IS NULL THEN
        RAISE EXCEPTION 'form_submission_signatures: drawn_asset_document_id not found';
    END IF;
    IF doc_org <> row_org THEN
        RAISE EXCEPTION 'form_submission_signatures: drawn asset document.org_id must match submission.org_id';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_oe_authority_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE prior_org uuid;
BEGIN
    NEW.recorded_at := now();
    IF NOT EXISTS (SELECT 1 FROM public.operational_authorities a WHERE a.org_id = NEW.org_id AND a.authority_key = NEW.authority_key) THEN
        RAISE EXCEPTION 'oe_authority_assignment: authority % is not governed in this org', NEW.authority_key USING ERRCODE = '23503';
    END IF;
    IF NEW.supersedes_assignment_id IS NOT NULL THEN
        SELECT org_id INTO prior_org FROM public.operational_authority_assignments WHERE id = NEW.supersedes_assignment_id;
        IF prior_org IS NULL OR prior_org <> NEW.org_id THEN
            RAISE EXCEPTION 'oe_authority_assignment: revocation must supersede a same-org grant' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_oe_ratification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    exp_org uuid;
    exp_modality text;
    exp_standing text;
    exp_root uuid;
BEGIN
    NEW.ratified_at := now(); -- server-assigned, non-forgeable

    SELECT e.org_id, e.modality, e.standing, e.lineage_root_id
    INTO exp_org, exp_modality, exp_standing, exp_root
    FROM public.operational_expectations e
    WHERE e.id = NEW.expectation_id;

    IF exp_org IS NULL THEN
        RAISE EXCEPTION 'oe_ratification: expectation % not found', NEW.expectation_id USING ERRCODE = '23503';
    END IF;
    IF exp_org <> NEW.org_id THEN
        RAISE EXCEPTION 'oe_ratification: cross-org ratification is forbidden' USING ERRCODE = '23514';
    END IF;
    IF exp_modality NOT IN ('required', 'prohibited', 'intended', 'committed') THEN
        RAISE EXCEPTION 'oe_ratification: only deontic/commissive expectations are ratifiable (got %)', exp_modality USING ERRCODE = '23514';
    END IF;
    IF exp_standing <> 'proposed' THEN
        RAISE EXCEPTION 'oe_ratification: only a proposed expectation may be ratified (got %)', exp_standing USING ERRCODE = '23514';
    END IF;

    NEW.prior_standing := exp_standing;
    IF NEW.lineage_root_id IS NULL THEN
        NEW.lineage_root_id := COALESCE(exp_root, NEW.expectation_id);
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_operational_expectations_lineage()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    prior_org uuid;
    prior_root uuid;
BEGIN
    -- Recorded (transaction) time is ALWAYS server-assigned — a caller may not
    -- forge it. Valid/effective time (valid_from) is separate and author-supplied.
    -- Immutability is guaranteed by the append-only trigger (no UPDATE).
    NEW.authored_at := now();

    IF NEW.verb = 'create' THEN
        -- A create roots its own lineage.
        IF NEW.lineage_root_id IS NULL THEN
            NEW.lineage_root_id := NEW.id;
        ELSIF NEW.lineage_root_id <> NEW.id THEN
            RAISE EXCEPTION 'operational_expectations: a create must root its own lineage' USING ERRCODE = '23514';
        END IF;
    ELSE
        SELECT e.org_id, e.lineage_root_id
        INTO prior_org, prior_root
        FROM public.operational_expectations e
        WHERE e.id = NEW.supersedes_expectation_id;

        IF prior_org IS NULL THEN
            RAISE EXCEPTION 'operational_expectations: supersedes_expectation_id % not found', NEW.supersedes_expectation_id
                USING ERRCODE = '23503';
        END IF;
        IF prior_org <> NEW.org_id THEN
            RAISE EXCEPTION 'operational_expectations: supersession must target a row on the same org' USING ERRCODE = '23514';
        END IF;
        -- Inherit the lineage root; default it when not supplied.
        IF NEW.lineage_root_id IS NULL THEN
            NEW.lineage_root_id := COALESCE(prior_root, NEW.supersedes_expectation_id);
        ELSIF NEW.lineage_root_id <> COALESCE(prior_root, NEW.supersedes_expectation_id) THEN
            RAISE EXCEPTION 'operational_expectations: lineage_root_id must match the superseded row''s root' USING ERRCODE = '23514';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_opportunity_customer_members_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    opp_org uuid;
    opp_customer uuid;
    mem_org uuid;
    mem_customer uuid;
BEGIN
    SELECT o.org_id, o.customer_id
    INTO opp_org, opp_customer
    FROM public.opportunities o
    WHERE o.id = NEW.opportunity_id;

    IF opp_org IS NULL THEN
        RAISE EXCEPTION 'opportunity_customer_members: opportunity_id % not found', NEW.opportunity_id;
    END IF;
    IF opp_org <> NEW.org_id THEN
        RAISE EXCEPTION 'opportunity_customer_members: org_id mismatch (row %, opp %)', NEW.org_id, opp_org;
    END IF;

    SELECT cm.org_id, cm.customer_id
    INTO mem_org, mem_customer
    FROM public.customer_members cm
    WHERE cm.id = NEW.customer_member_id;

    IF mem_org IS NULL THEN
        RAISE EXCEPTION 'opportunity_customer_members: customer_member_id % not found', NEW.customer_member_id;
    END IF;
    IF mem_org <> NEW.org_id THEN
        RAISE EXCEPTION 'opportunity_customer_members: org_id mismatch (row %, member %)', NEW.org_id, mem_org;
    END IF;

    -- If the opportunity is linked to a family/customer, enforce member belongs to same family.
    IF opp_customer IS NOT NULL AND mem_customer IS NOT NULL AND mem_customer <> opp_customer THEN
        RAISE EXCEPTION 'opportunity_customer_members: customer_member.customer_id % does not match opportunity.customer_id %', mem_customer, opp_customer;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_opportunity_persons_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    opp_org uuid;
    person_org uuid;
BEGIN
    SELECT o.org_id INTO opp_org FROM public.opportunities o WHERE o.id = NEW.opportunity_id;
    IF opp_org IS NULL THEN
        RAISE EXCEPTION 'opportunity_persons: opportunity_id % not found', NEW.opportunity_id;
    END IF;
    IF NEW.org_id IS DISTINCT FROM opp_org THEN
        RAISE EXCEPTION 'opportunity_persons: org_id mismatch (row %, opportunity %)', NEW.org_id, opp_org;
    END IF;

    SELECT p.org_id INTO person_org FROM public.persons p WHERE p.id = NEW.person_id;
    IF person_org IS NULL THEN
        RAISE EXCEPTION 'opportunity_persons: person_id % not found', NEW.person_id;
    END IF;
    IF NEW.org_id IS DISTINCT FROM person_org THEN
        RAISE EXCEPTION 'opportunity_persons: org_id mismatch (row %, person %)', NEW.org_id, person_org;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_person_child_relationship_roles_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    rel_org uuid;
    rel_status text;
BEGIN
    SELECT r.org_id, r.status INTO rel_org, rel_status
    FROM public.person_child_relationships r WHERE r.id = NEW.relationship_id;
    IF rel_org IS NULL THEN
        RAISE EXCEPTION 'person_child_relationship_roles: relationship_id % not found', NEW.relationship_id;
    END IF;
    IF NEW.org_id IS DISTINCT FROM rel_org THEN
        RAISE EXCEPTION 'person_child_relationship_roles: org_id mismatch with relationship';
    END IF;
    IF rel_status = 'inactive' AND NEW.is_active = true THEN
        RAISE EXCEPTION 'person_child_relationship_roles: cannot activate role on inactive relationship';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_person_child_relationships_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    cust_org uuid;
    member_org uuid;
    member_customer uuid;
    person_org uuid;
BEGIN
    SELECT c.org_id INTO cust_org FROM public.customers c WHERE c.id = NEW.customer_id;
    IF cust_org IS NULL THEN
        RAISE EXCEPTION 'person_child_relationships: customer_id % not found', NEW.customer_id;
    END IF;
    IF NEW.org_id IS DISTINCT FROM cust_org THEN
        RAISE EXCEPTION 'person_child_relationships: org_id mismatch with customer';
    END IF;

    SELECT cm.org_id, cm.customer_id INTO member_org, member_customer
    FROM public.customer_members cm WHERE cm.id = NEW.customer_member_id;
    IF member_org IS NULL THEN
        RAISE EXCEPTION 'person_child_relationships: customer_member_id % not found', NEW.customer_member_id;
    END IF;
    IF NEW.org_id IS DISTINCT FROM member_org THEN
        RAISE EXCEPTION 'person_child_relationships: org_id mismatch with customer_member';
    END IF;
    IF NEW.customer_id IS DISTINCT FROM member_customer THEN
        RAISE EXCEPTION 'person_child_relationships: customer_id mismatch with customer_member';
    END IF;

    SELECT p.org_id INTO person_org FROM public.persons p WHERE p.id = NEW.person_id;
    IF person_org IS NULL THEN
        RAISE EXCEPTION 'person_child_relationships: person_id % not found', NEW.person_id;
    END IF;
    IF NEW.org_id IS DISTINCT FROM person_org THEN
        RAISE EXCEPTION 'person_child_relationships: org_id mismatch with person';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_placement_candidates_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    opp_org uuid;
    opp_customer uuid;
    ocm_org uuid;
    ocm_opp uuid;
    ocm_member uuid;
    mem_org uuid;
    mem_customer uuid;
    person_org uuid;
    site_org uuid;
BEGIN
    SELECT o.org_id, o.customer_id
    INTO opp_org, opp_customer
    FROM public.opportunities o
    WHERE o.id = NEW.opportunity_id;

    IF opp_org IS NULL THEN
        RAISE EXCEPTION 'placement_candidates: opportunity_id % not found', NEW.opportunity_id
            USING ERRCODE = '23503';
    END IF;
    IF opp_org <> NEW.org_id THEN
        RAISE EXCEPTION 'placement_candidates: org_id mismatch with opportunity'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.customer_id IS NOT NULL AND opp_customer IS NOT NULL AND NEW.customer_id <> opp_customer THEN
        RAISE EXCEPTION 'placement_candidates: customer_id does not match opportunity.customer_id'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.opportunity_customer_member_id IS NOT NULL THEN
        SELECT ocm.org_id, ocm.opportunity_id, ocm.customer_member_id
        INTO ocm_org, ocm_opp, ocm_member
        FROM public.opportunity_customer_members ocm
        WHERE ocm.id = NEW.opportunity_customer_member_id;

        IF ocm_org IS NULL THEN
            RAISE EXCEPTION 'placement_candidates: opportunity_customer_member_id % not found', NEW.opportunity_customer_member_id
                USING ERRCODE = '23503';
        END IF;
        IF ocm_org <> NEW.org_id OR ocm_opp <> NEW.opportunity_id THEN
            RAISE EXCEPTION 'placement_candidates: OCM org/opportunity mismatch'
                USING ERRCODE = '23514';
        END IF;

        IF NEW.customer_member_id IS NULL THEN
            NEW.customer_member_id := ocm_member;
        ELSIF NEW.customer_member_id <> ocm_member THEN
            RAISE EXCEPTION 'placement_candidates: customer_member_id does not match OCM row'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NEW.customer_member_id IS NOT NULL THEN
        SELECT cm.org_id, cm.customer_id
        INTO mem_org, mem_customer
        FROM public.customer_members cm
        WHERE cm.id = NEW.customer_member_id;

        IF mem_org IS NULL THEN
            RAISE EXCEPTION 'placement_candidates: customer_member_id % not found', NEW.customer_member_id
                USING ERRCODE = '23503';
        END IF;
        IF mem_org <> NEW.org_id THEN
            RAISE EXCEPTION 'placement_candidates: customer_member org mismatch'
                USING ERRCODE = '23514';
        END IF;
        IF opp_customer IS NOT NULL AND mem_customer IS NOT NULL AND mem_customer <> opp_customer THEN
            RAISE EXCEPTION 'placement_candidates: customer_member customer mismatch with opportunity'
                USING ERRCODE = '23514';
        END IF;

        IF NEW.person_id IS NULL THEN
            SELECT cm.person_id INTO NEW.person_id
            FROM public.customer_members cm
            WHERE cm.id = NEW.customer_member_id;
        END IF;
    END IF;

    IF NEW.person_id IS NOT NULL THEN
        SELECT p.org_id INTO person_org FROM public.persons p WHERE p.id = NEW.person_id;
        IF person_org IS NULL THEN
            RAISE EXCEPTION 'placement_candidates: person_id % not found', NEW.person_id USING ERRCODE = '23503';
        END IF;
        IF person_org <> NEW.org_id THEN
            RAISE EXCEPTION 'placement_candidates: person org mismatch' USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NEW.site_id IS NOT NULL THEN
        SELECT l.org_id INTO site_org FROM public.locations l WHERE l.id = NEW.site_id;
        IF site_org IS NULL THEN
            RAISE EXCEPTION 'placement_candidates: site_id % not found', NEW.site_id USING ERRCODE = '23503';
        END IF;
        IF site_org <> NEW.org_id THEN
            RAISE EXCEPTION 'placement_candidates: site org mismatch' USING ERRCODE = '23514';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_placement_link_group_members_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    grp_org uuid;
    grp_opp uuid;
    cand_org uuid;
    cand_opp uuid;
BEGIN
    SELECT g.org_id, g.opportunity_id INTO grp_org, grp_opp
    FROM public.placement_link_groups g WHERE g.id = NEW.placement_link_group_id;

    IF grp_org IS NULL THEN
        RAISE EXCEPTION 'placement_link_group_members: group % not found', NEW.placement_link_group_id USING ERRCODE = '23503';
    END IF;

    SELECT c.org_id, c.opportunity_id INTO cand_org, cand_opp
    FROM public.placement_candidates c WHERE c.id = NEW.placement_candidate_id;

    IF cand_org IS NULL THEN
        RAISE EXCEPTION 'placement_link_group_members: candidate % not found', NEW.placement_candidate_id USING ERRCODE = '23503';
    END IF;

    IF NEW.org_id <> grp_org OR NEW.org_id <> cand_org THEN
        RAISE EXCEPTION 'placement_link_group_members: org_id mismatch' USING ERRCODE = '23514';
    END IF;
    IF grp_opp <> cand_opp THEN
        RAISE EXCEPTION 'placement_link_group_members: group and candidate opportunity mismatch' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_placement_link_groups_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    opp_org uuid;
    opp_customer uuid;
BEGIN
    SELECT o.org_id, o.customer_id INTO opp_org, opp_customer
    FROM public.opportunities o WHERE o.id = NEW.opportunity_id;

    IF opp_org IS NULL THEN
        RAISE EXCEPTION 'placement_link_groups: opportunity_id % not found', NEW.opportunity_id USING ERRCODE = '23503';
    END IF;
    IF opp_org <> NEW.org_id THEN
        RAISE EXCEPTION 'placement_link_groups: org_id mismatch' USING ERRCODE = '23514';
    END IF;
    IF NEW.customer_id IS NOT NULL AND opp_customer IS NOT NULL AND NEW.customer_id <> opp_customer THEN
        RAISE EXCEPTION 'placement_link_groups: customer_id mismatch' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_placement_overrides_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    cand_org uuid;
    cand_cohort text;
BEGIN
    SELECT c.org_id, c.program_room_cohort_key
    INTO cand_org, cand_cohort
    FROM public.placement_candidates c
    WHERE c.id = NEW.placement_candidate_id;

    IF cand_org IS NULL THEN
        RAISE EXCEPTION 'placement_overrides: candidate % not found', NEW.placement_candidate_id USING ERRCODE = '23503';
    END IF;
    IF cand_org <> NEW.org_id THEN
        RAISE EXCEPTION 'placement_overrides: org_id mismatch' USING ERRCODE = '23514';
    END IF;
    IF btrim(NEW.program_room_cohort_key) <> btrim(cand_cohort) THEN
        RAISE EXCEPTION 'placement_overrides: program_room_cohort_key must match candidate cohort'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_schedule_assignments_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    agr_org uuid;
    agr_member uuid;
    agr_site uuid;
    pat_org uuid;
    pat_site uuid;
BEGIN
    SELECT a.org_id, a.customer_member_id, a.site_location_id
    INTO agr_org, agr_member, agr_site
    FROM public.child_enrollment_agreements a
    WHERE a.id = NEW.enrollment_agreement_id;

    IF agr_org IS NULL THEN
        RAISE EXCEPTION 'schedule_assignments: enrollment_agreement_id % not found', NEW.enrollment_agreement_id
            USING ERRCODE = '23503';
    END IF;
    IF agr_org <> NEW.org_id THEN
        RAISE EXCEPTION 'schedule_assignments: agreement org mismatch'
            USING ERRCODE = '23514';
    END IF;
    IF agr_member <> NEW.customer_member_id THEN
        RAISE EXCEPTION 'schedule_assignments: customer_member_id does not match agreement'
            USING ERRCODE = '23514';
    END IF;

    SELECT sp.org_id, sp.site_location_id
    INTO pat_org, pat_site
    FROM public.schedule_patterns sp
    WHERE sp.id = NEW.schedule_pattern_id;

    IF pat_org IS NULL THEN
        RAISE EXCEPTION 'schedule_assignments: schedule_pattern_id % not found', NEW.schedule_pattern_id
            USING ERRCODE = '23503';
    END IF;
    IF pat_org <> NEW.org_id OR pat_site <> agr_site THEN
        RAISE EXCEPTION 'schedule_assignments: schedule_pattern must belong to agreement site'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_schedule_patterns_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    site_org uuid;
    site_type text;
BEGIN
    SELECT l.org_id, l.location_type
    INTO site_org, site_type
    FROM public.locations l
    WHERE l.id = NEW.site_location_id;

    IF site_org IS NULL THEN
        RAISE EXCEPTION 'schedule_patterns: site_location_id % not found', NEW.site_location_id
            USING ERRCODE = '23503';
    END IF;
    IF site_org <> NEW.org_id THEN
        RAISE EXCEPTION 'schedule_patterns: site org mismatch'
            USING ERRCODE = '23514';
    END IF;
    IF site_type IS DISTINCT FROM 'site' THEN
        RAISE EXCEPTION 'schedule_patterns: site_location_id % must be location_type site (got %)',
            NEW.site_location_id, site_type
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_schedule_patterns_weekdays()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    d smallint;
BEGIN
    IF NEW.weekdays IS NULL OR cardinality(NEW.weekdays) = 0 THEN
        RAISE EXCEPTION 'schedule_patterns.weekdays must be non-empty'
            USING ERRCODE = '23514';
    END IF;

    FOREACH d IN ARRAY NEW.weekdays
    LOOP
        IF d < 0 OR d > 6 THEN
            RAISE EXCEPTION 'schedule_patterns.weekdays element % out of range 0-6', d
                USING ERRCODE = '23514';
        END IF;
    END LOOP;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_tour_availability_rules_location_org()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    loc_org uuid;
BEGIN
    IF NEW.location_id IS NULL THEN
        RETURN NEW;
    END IF;
    SELECT l.org_id INTO loc_org FROM public.locations l WHERE l.id = NEW.location_id;
    IF loc_org IS NULL THEN
        RAISE EXCEPTION 'tour_availability_rules: location_id % not found', NEW.location_id;
    END IF;
    IF loc_org IS DISTINCT FROM NEW.org_id THEN
        RAISE EXCEPTION 'tour_availability_rules: location_id must belong to org_id';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_tour_booking_org_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    opp_org uuid;
    loc_org uuid;
    fs_org uuid;
    fpl_org uuid;
    parent_org uuid;
BEGIN
    SELECT o.org_id INTO opp_org FROM public.opportunities o WHERE o.id = NEW.opportunity_id;
    IF opp_org IS NULL THEN
        RAISE EXCEPTION 'tour_bookings: opportunity_id % not found', NEW.opportunity_id;
    END IF;
    IF NEW.org_id IS DISTINCT FROM opp_org THEN
        RAISE EXCEPTION 'tour_bookings: org_id must match opportunities.org_id for opportunity_id';
    END IF;

    SELECT l.org_id INTO loc_org FROM public.locations l WHERE l.id = NEW.location_id;
    IF loc_org IS NULL THEN
        RAISE EXCEPTION 'tour_bookings: location_id % not found', NEW.location_id;
    END IF;
    IF loc_org IS DISTINCT FROM NEW.org_id THEN
        RAISE EXCEPTION 'tour_bookings: location_id must belong to the same org_id';
    END IF;

    IF NEW.form_submission_id IS NOT NULL THEN
        SELECT fs.org_id INTO fs_org FROM public.form_submissions fs WHERE fs.id = NEW.form_submission_id;
        IF fs_org IS NULL THEN
            RAISE EXCEPTION 'tour_bookings: form_submission_id % not found', NEW.form_submission_id;
        END IF;
        IF fs_org IS DISTINCT FROM NEW.org_id THEN
            RAISE EXCEPTION 'tour_bookings: form_submission_id org_id mismatch';
        END IF;
    END IF;

    IF NEW.form_public_link_id IS NOT NULL THEN
        SELECT fpl.org_id INTO fpl_org FROM public.form_public_links fpl WHERE fpl.id = NEW.form_public_link_id;
        IF fpl_org IS NULL THEN
            RAISE EXCEPTION 'tour_bookings: form_public_link_id % not found', NEW.form_public_link_id;
        END IF;
        IF fpl_org IS DISTINCT FROM NEW.org_id THEN
            RAISE EXCEPTION 'tour_bookings: form_public_link_id org_id mismatch';
        END IF;
    END IF;

    IF NEW.rescheduled_from_booking_id IS NOT NULL THEN
        SELECT tb.org_id INTO parent_org FROM public.tour_bookings tb WHERE tb.id = NEW.rescheduled_from_booking_id;
        IF parent_org IS NULL THEN
            RAISE EXCEPTION 'tour_bookings: rescheduled_from_booking_id % not found', NEW.rescheduled_from_booking_id;
        END IF;
        IF parent_org IS DISTINCT FROM NEW.org_id THEN
            RAISE EXCEPTION 'tour_bookings: rescheduled_from_booking_id org_id mismatch';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_tour_public_booking_link_scope()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    opp_org uuid;
    loc_org uuid;
BEGIN
    SELECT o.org_id INTO opp_org FROM public.opportunities o WHERE o.id = NEW.opportunity_id;
    IF opp_org IS NULL THEN
        RAISE EXCEPTION 'tour_public_booking_links: opportunity_id % not found', NEW.opportunity_id;
    END IF;
    IF opp_org IS DISTINCT FROM NEW.org_id THEN
        RAISE EXCEPTION 'tour_public_booking_links: opportunity org_id mismatch';
    END IF;

    SELECT l.org_id INTO loc_org FROM public.locations l WHERE l.id = NEW.location_id;
    IF loc_org IS NULL THEN
        RAISE EXCEPTION 'tour_public_booking_links: location_id % not found', NEW.location_id;
    END IF;
    IF loc_org IS DISTINCT FROM NEW.org_id THEN
        RAISE EXCEPTION 'tour_public_booking_links: location org_id mismatch';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_user_department_access_org_match()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    d_org uuid;
BEGIN
    SELECT d.org_id INTO d_org
    FROM public.departments AS d
    WHERE d.id = NEW.department_id;

    IF d_org IS NULL THEN
        RAISE EXCEPTION 'user_department_access: department_id % does not exist', NEW.department_id
            USING ERRCODE = '23503';
    END IF;

    IF d_org <> NEW.org_id THEN
        RAISE EXCEPTION 'user_department_access: org_id on row (%) must match departments.org_id (%) for department_id %',
            NEW.org_id, d_org, NEW.department_id
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_user_site_access_site_and_org()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    loc_org uuid;
    loc_type text;
BEGIN
    SELECT l.org_id, l.location_type
    INTO loc_org, loc_type
    FROM public.locations AS l
    WHERE l.id = NEW.location_id;

    IF loc_org IS NULL THEN
        RAISE EXCEPTION 'user_site_access: location_id % does not exist', NEW.location_id
            USING ERRCODE = '23503';
    END IF;

    IF loc_org <> NEW.org_id THEN
        RAISE EXCEPTION 'user_site_access: org_id on row (%) must match locations.org_id (%) for location_id %',
            NEW.org_id, loc_org, NEW.location_id
            USING ERRCODE = '23514';
    END IF;

    IF loc_type IS DISTINCT FROM 'site'::text THEN
        RAISE EXCEPTION 'user_site_access: location_id % must have location_type = site (got %)',
            NEW.location_id, loc_type
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.workflow_runs_set_org_id()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.org_id is null then
    new.org_id := nullif(new.event_payload->>'org_id','')::uuid;
  end if;
  return new;
end;
$function$
